-- Other right English answers for the sentences whose Spanish and English were
-- both rewritten in 20261005000009 and 20: their old alternatives answered
-- another sentence and were rightly dropped, and nothing wrote new ones.
-- A sentence edited since (its text no longer matches) is left alone.
update public.sentences s set en_alt = v.en_alt, updated_at = now()
from (values
  ('00a82c61-0fcd-5d36-804e-f8da8df4ac4f', 'Me encanta escuchar música todo el día.', 'I love listening to music all day.', array['I love to listen to music all day.', 'I love listening to music all day long.']::text[]),
  ('027c864f-d4c6-5697-acbb-06f2a9aaed71', 'Le dejé las llaves a Sofi porque es de confianza.', 'I left the keys with Sofi because I trust her.', array['I left Sofi the keys because I trust her.', 'I left the keys with Sofi because she''s trustworthy.']::text[]),
  ('0327043e-04cd-5095-89ae-1aa9e8be339e', 'Acampamos entre dos lagos, cerca de la cordillera.', 'We camped between two lakes, near the Andes.', array['We camped between two lakes, close to the Andes.', 'We camped between two lakes, near the mountains.']::text[]),
  ('04ca8e6a-f009-56bc-8145-201ecc3787b2', 'Él es mi papá, se llama Carlos.', 'He''s my dad, his name is Carlos.', array['He is my dad, his name is Carlos.', 'He''s my dad, he''s called Carlos.']::text[]),
  ('0637af7e-d7b3-5c52-92a8-e4053f6b4676', 'Viajamos este viernes temprano.', 'We''re traveling early this Friday.', array['We travel early this Friday.', 'We''re leaving early this Friday.']::text[]),
  ('06f250a9-8179-5270-8d9c-c48228db95d7', 'El gremio docente anunció una medida de fuerza.', 'The teachers'' union announced a strike.', array['The teachers'' union announced a walkout.', 'The teachers'' union called a strike.']::text[]),
  ('06f8906c-487d-595c-9a95-090f0cc2866c', 'Me da un poco de miedo, pero viajar sola me hace bien.', 'It scares me a little, but traveling alone does me good.', array['It scares me a bit, but traveling alone is good for me.', 'I''m a little scared, but traveling alone does me good.']::text[]),
  ('0709543d-681b-5fd9-86ac-bf20f71d5e0a', '—Ella es alemana, ¿no? —No, es inglesa.', '—She''s German, right? —No, she''s English.', array['She''s German, isn''t she? No, she''s English.', 'She is German, right? No, she is English.']::text[]),
  ('080eaa38-2e0c-50cd-9e0c-6ac72348cf8c', 'Algún día quiero lograr algo grande.', 'Someday I want to achieve something big.', array['One day I want to achieve something big.', 'Someday I want to accomplish something big.']::text[]),
  ('08de422a-8d46-5318-90dd-bb79c874ed6b', 'Otra vez se me quemó la comida.', 'I burned the food again.', array['The food got burned again.', 'I burnt the food again.']::text[]),
  ('09333679-566b-565f-8724-d60775223a85', 'Recorrimos el norte con Lucía y vimos las cataratas.', 'We traveled around the north with Lucía and saw the waterfalls.', array['We toured the north with Lucía and saw the waterfalls.', 'We traveled around the north with Lucía and we saw the falls.']::text[]),
  ('09d6488b-4caf-5ddb-89fe-4140e0d598ff', 'Ese pantalón naranja es re feo.', 'Those orange pants are really ugly.', array['Those orange pants are so ugly.', 'Those orange pants are super ugly.']::text[]),
  ('0a4bd5bb-1a07-5866-8d02-6fb3ad4beb5b', 'Frená antes, que la ruta está mojada.', 'Brake earlier, the highway is wet.', array['Brake sooner, the road is wet.', 'Brake earlier, the road is wet.']::text[]),
  ('0a80ee5a-82bc-5698-a43d-70ef1be2b3b2', 'Le pregunté a Sofi si viene al asado.', 'I asked Sofi if she''s coming to the asado.', array['I asked Sofi whether she''s coming to the asado.', 'I asked Sofi if she''s coming to the barbecue.']::text[]),
  ('0b1420e4-e409-5e04-a0e7-1289a7fe8270', '—¿Tu mamá es morocha? —No, rubia.', '—Does your mom have dark hair? —No, she''s blonde.', array['Is your mom dark-haired? No, blonde.', 'Does your mom have dark hair? No, blonde.']::text[]),
  ('0cf02fb4-cf0f-57c9-ba71-1a5cac6a4ba7', '¿Dónde dejaste el formulario?', 'Where did you leave the form?', array['Where did you put the form?', 'Where''d you leave the form?']::text[]),
  ('0e979250-c356-5ceb-8dd2-ac4795993afb', 'Ojo en el subte, siempre hay un punga.', 'Watch out on the subway, there''s always a pickpocket.', array['Be careful on the subway, there''s always a pickpocket.', 'Watch out in the subway, there''s always a pickpocket.']::text[]),
  ('0f932f59-fa2f-5e96-839b-bf4b0badf4ca', 'Lucía aclaró que no le trajera nada.', 'Lucía made it clear I shouldn''t bring her anything.', array['Lucía made it clear that I shouldn''t bring her anything.', 'Lucía made it clear not to bring her anything.']::text[]),
  ('113cce28-cc8c-5993-ad45-fe6ae00ead4c', 'Dejé pasar el tren porque venía lleno.', 'I skipped the train because it was full.', array['I let the train go by because it was full.', 'I let the train pass because it was packed.']::text[]),
  ('126ce911-2c89-531e-bc80-56f3b0e3e9ea', 'El tiempo empeoró y volvimos a casa.', 'The weather got worse and we went back home.', array['The weather got worse and we went home.', 'The weather worsened and we went back home.']::text[]),
  ('136e9d0a-591f-5445-8d8c-618bd33d1e91', 'Me preocupa que vivas tan lejos del laburo.', 'It worries me that you live so far from work.', array['I''m worried that you live so far from work.', 'It worries me that you live so far away from work.']::text[]),
  ('13705278-8039-5fe6-826a-8b889b6d0ad4', 'El dueño, supuestamente, acepta mascotas.', 'The landlord supposedly allows pets.', array['Supposedly, the landlord allows pets.', 'The owner supposedly accepts pets.']::text[]),
  ('13771c02-0ffe-5b47-ac3e-63bf9c9930d4', 'Siempre tomaba café con leche.', 'I always drank coffee with milk.', array['I always used to drink coffee with milk.', 'I always had coffee with milk.']::text[]),
  ('13782222-c883-5832-85ac-6cabb7949bda', 'Mi sobrina tiene once años.', 'My niece is eleven.', array['My niece is eleven years old.']::text[]),
  ('13a17b22-3536-542b-9e84-37df3ad418ed', 'Tuve una semana re mala en el laburo.', 'I had a really bad week at work.', array['I had a really bad week at the office.', 'I had a terrible week at work.']::text[]),
  ('14c2eea0-b05c-5cf7-b2a9-e04f9cc615a7', 'El vino acá es baratísimo.', 'Wine here is very cheap.', array['Wine is very cheap here.', 'The wine here is super cheap.']::text[]),
  ('14c3a8e7-705e-5a51-b85d-2e4bd6d1da12', 'En la tele dicen que mañana sigue la medida de fuerza.', 'On TV they say the strike continues tomorrow.', array['On TV they''re saying the strike continues tomorrow.', 'They say on TV that the strike goes on tomorrow.']::text[]),
  ('157a22d2-8253-5009-addf-f63f09603f9f', 'El plomero arregló la pérdida.', 'The plumber fixed the leak.', array['The plumber repaired the leak.']::text[]),
  ('15c03cd0-7309-5df7-9563-04118d2cf403', 'Estamos dos días en Córdoba.', 'We''re in Córdoba for two days.', array['We''re spending two days in Córdoba.', 'We are in Córdoba for two days.']::text[]),
  ('164ba2f2-c212-5713-b5ea-514d81a331c1', 'La reunión supuestamente es a las diez, pero no hay nadie.', 'The meeting is supposedly at ten, but nobody''s here.', array['Supposedly the meeting is at ten, but no one''s here.', 'The meeting is supposedly at ten, but there''s nobody here.']::text[]),
  ('16fc8d3b-3c67-5722-918b-fd3a003a2070', '—¿Me pasás la sal? —Cómo no, acá tenés.', '—Can you pass me the salt? —Of course, here you go.', array['Can you pass me the salt? Sure, here you go.', 'Will you pass me the salt? Of course, here you are.']::text[]),
  ('176fe619-aa54-5347-9ae0-4b41608fc3ac', 'Se me rompió la compu.', 'My computer broke.', array['My computer broke down.', 'My laptop broke.']::text[]),
  ('17713e43-0ea4-5442-9af6-0bfa02e66aad', 'Don José es jubilado y juega al fútbol con su nieto.', 'Don José is retired and plays soccer with his grandson.', array['Don José is retired and he plays soccer with his grandson.', 'Mr. José is retired and plays soccer with his grandson.']::text[]),
  ('17fd4e92-9c62-515f-9ca8-f05a7442fa55', 'Hoy hay viento en la playa.', 'It''s windy at the beach today.', array['It''s windy on the beach today.', 'Today it''s windy at the beach.']::text[]),
  ('1a30cab7-2f5e-5b9d-9daa-0c723affbea4', 'Esta vez viajamos en micro.', 'This time we''re traveling by bus.', array['This time we''re going by bus.', 'This time we travel by bus.']::text[]),
  ('1aa96d53-5530-5a59-a143-bac56b0d4f08', 'Acabás de llegar, ¿ya te vas?', 'You just got here, are you leaving already?', array['You just arrived, are you leaving already?', 'You just got here, you''re leaving already?']::text[]),
  ('1ac77197-ab54-58c5-b8eb-04848ac82fb8', 'Busco a alguien que no fume y que comparta los gastos.', 'I''m looking for someone who doesn''t smoke and shares the costs.', array['I''m looking for someone who doesn''t smoke and who shares expenses.', 'I''m looking for someone who doesn''t smoke and splits the costs.']::text[]),
  ('1ad603d4-9484-5f71-a5aa-bc342bc86a53', 'Faltaba más, doña Marta, te llevo la bolsa.', 'Of course, Doña Marta, I''ll carry your bag.', array['Don''t mention it, Doña Marta, I''ll carry your bag.', 'Of course, Doña Marta, I''ll carry the bag for you.']::text[]),
  ('1b4b6c45-f598-5e35-af4d-041f90043339', 'Vengo en bondi todos los días.', 'I come here by bus every day.', array['I come by bus every day.', 'I take the bus here every day.']::text[]),
  ('1b4fe546-7142-5093-a0f7-fbfa1c5703a3', '¿Otra tostada?', 'Another piece of toast?', array['Another toast?', 'More toast?']::text[]),
  ('1bfb98fe-758a-57c7-8fa3-c21813f9bb40', 'Esta noche voy a cantar en un bar de San Telmo.', 'Tonight I''m going to sing at a bar in San Telmo.', array['Tonight I''m singing at a bar in San Telmo.', 'I''m going to sing at a bar in San Telmo tonight.']::text[]),
  ('1c14ad05-783b-55cb-848b-95a80f40b5de', 'Los dos son altos, pero Santi es rubio y Nico es morocho.', 'They''re both tall, but Santi is blond and Nico is dark-haired.', array['Both are tall, but Santi is blond and Nico has dark hair.', 'They''re both tall, but Santi is blonde and Nico is dark-haired.']::text[]),
  ('1d35042f-58b5-54f0-9d9b-85018bf8e43b', 'El hospital más cercano queda a diez cuadras.', 'The nearest hospital is ten blocks away.', array['The closest hospital is ten blocks away.', 'The nearest hospital is ten blocks from here.']::text[]),
  ('1dd92014-987a-5ab3-8778-620f005c1d05', '¿Falleció tu tía? Te acompaño en el sentimiento.', 'Your aunt passed away? I''m sorry for your loss.', array['Did your aunt pass away? I''m sorry for your loss.', 'Your aunt died? My condolences.']::text[]),
  ('1e1e41e7-2c89-5c4c-9235-94889a8558af', '¿Ves ese edificio? Yo vivo ahí.', 'Can you see that building? I live there.', array['Do you see that building? I live there.', 'See that building? I live there.']::text[]),
  ('1e4ad9a1-1690-5d5c-80ca-70928069efc6', 'Diego estuvo re zarpado con lo que dijo.', 'Diego was really out of line with what he said.', array['Diego was way out of line with what he said.', 'Diego really crossed the line with what he said.']::text[]),
  ('1e6e1f93-d732-563a-b509-46a941124467', '—¿Qué te tocó para el asado? —El postre.', '—What were you asked to bring to the asado? —Dessert.', array['What did you get for the asado? Dessert.', 'What do you have to bring to the asado? Dessert.']::text[]),
  ('1f4a4204-36f7-5d65-8851-c85a5e32fc2b', 'Ella no es argentina, es inglesa.', 'She isn''t Argentinian, she''s English.', array['She''s not Argentinian, she''s English.', 'She isn''t Argentine, she''s English.']::text[]),
  ('1fb645b7-c014-53b3-8569-3798589f9504', 'Mi perro es genial.', 'My dog is great.', array['My dog is awesome.', 'My dog''s great.']::text[]),
  ('1fdda350-c349-5451-85bc-c450fe6cbd76', 'El servicio de tren está suspendido, así que mañana laburo desde casa.', 'The train service is suspended, so I''m working from home tomorrow.', array['Train service is suspended, so tomorrow I''m working from home.', 'The train service is suspended, so I''ll work from home tomorrow.']::text[]),
  ('2038b6a6-e5e1-54bd-9424-0c58ac02109a', 'Ella es mi mamá, se llama Elena.', 'She''s my mom, her name is Elena.', array['She is my mom, her name is Elena.', 'She''s my mom, she''s called Elena.']::text[]),
  ('2063b3bc-832f-50d2-906f-5af3082bb183', 'Para sacar el pasaje necesitás el pasaporte.', 'To buy the ticket you need your passport.', array['You need your passport to buy the ticket.', 'To get the ticket you need your passport.']::text[]),
  ('21e053f1-7860-5d48-9476-9ded3b2f1a69', 'El sábado me mudé a lo de mis viejos.', 'On Saturday I moved to my parents'' place.', array['On Saturday I moved in with my parents.', 'I moved to my parents'' place on Saturday.']::text[]),
  ('24893c70-a49c-556a-8e8d-362e1ede78cc', '¿Qué querés para tu cumple? ¿Una tele?', 'What do you want for your birthday? A TV?', array['What do you want for your birthday? A television?']::text[]),
  ('24b14450-3062-5748-911b-aee460c4e1c0', 'No uses el celu en la calle.', 'Don''t use your phone on the street.', array['Don''t use your cell phone on the street.', 'Don''t use your phone in the street.']::text[]),
  ('24f8396b-f4c6-5bf6-9658-4f4b506eb4c2', 'Mi jefa no es estricta, es re tranqui.', 'My boss isn''t strict, she''s really relaxed.', array['My boss isn''t strict, she''s really chill.', 'My boss isn''t strict, she''s super relaxed.']::text[]),
  ('251e1c5b-a00d-58f6-8bf3-fa310b1ec57e', 'Dejé los papeles en el banco.', 'I left the papers at the bank.', array['I left the documents at the bank.', 'I left the paperwork at the bank.']::text[]),
  ('2560926e-f758-5e55-be33-c11327cef747', '¿Anoche te asustaste con la lluvia y el viento?', 'Did the rain and the wind scare you last night?', array['Did you get scared by the rain and the wind last night?', 'Were you scared by the rain and wind last night?']::text[]),
  ('25a9f80a-25c0-57b6-8445-a200fb0c12f8', '¿Se enteraron de que Mati renunció?', 'Did you guys hear that Mati quit?', array['Did you hear that Mati quit?', 'Did you all hear that Mati resigned?']::text[]),
  ('25d05f7c-ed34-5ccf-bf4b-3139de461bae', 'A Lucía le duele la cabeza.', 'Lucía''s head hurts.', array['Lucía has a headache.', 'Lucía''s head is hurting.']::text[]),
  ('266d8469-dcfa-517d-864c-ae7c899c38cd', '¿Perdiste el laburo? Lo siento, Juan.', 'You lost your job? I''m sorry, Juan.', array['Did you lose your job? I''m sorry, Juan.', 'You lost your job? Sorry, Juan.']::text[]),
  ('26b00e5d-869f-5564-a47a-07fcf9e04e18', 'El bar se va llenando de a poco.', 'The bar is filling up little by little.', array['The bar is slowly filling up.', 'The bar is filling up bit by bit.']::text[]),
  ('26db22e4-07d6-59d6-953a-f4ca8cb266c8', '—¿Adónde vas el sábado? —Al boliche con Rocío.', '—Where are you going on Saturday? —To the nightclub with Rocío.', array['Where are you going Saturday? To the club with Rocío.', 'Where are you going on Saturday? To the club with Rocío.']::text[]),
  ('27476556-26dd-5810-8722-89aab4a88d6c', 'Mañana es el cumple de Mica y se me pasó comprar el regalo.', 'Tomorrow is Mica''s birthday and I forgot to buy the present.', array['Tomorrow is Mica''s birthday and I forgot to buy the gift.', 'It''s Mica''s birthday tomorrow and I forgot to buy the present.']::text[]),
  ('288f410d-234c-5a6b-93aa-db2b29c880f8', '—¿Rocío es rubia? —No, morocha.', '—Is Rocío blonde? —No, dark-haired.', array['Is Rocío blonde? No, she has dark hair.', 'Is Rocío blond? No, dark-haired.']::text[]),
  ('28dece1d-7eb1-5911-9327-2ee044c9d732', 'Pablo llega hoy, supuestamente.', 'Pablo arrives today, supposedly.', array['Supposedly, Pablo arrives today.', 'Pablo is supposedly arriving today.']::text[]),
  ('29212cd4-3259-5ecf-9de5-520ca9800ac1', 'Quedate en casa y que te mejores.', 'Stay home and get well soon.', array['Stay home and feel better.', 'Stay at home and get well soon.']::text[]),
  ('293d32d4-9076-509e-a95d-fda545e0f901', 'Preguntá por los caños antes de alquilar el depto.', 'Ask about the pipes before renting the apartment.', array['Ask about the pipes before you rent the apartment.']::text[]),
  ('29755fb7-63cb-513e-b3c1-93756ce64a79', 'Por fin se fue el calor, ¡qué alivio!', 'The heat is finally gone, what a relief!', array['The heat is finally over, what a relief!', 'Finally the heat is gone, what a relief!']::text[]),
  ('29b12f22-6e3a-58fb-9f53-bb4df5590de7', 'Nos olvidamos de reservar y no había mesa.', 'We forgot to book and there were no tables.', array['We forgot to make a reservation and there were no tables.', 'We forgot to reserve and there was no table.']::text[]),
  ('2ba5462b-8bb3-502c-be22-2ec179e5fffc', 'Nico jugaba al tenis.', 'Nico used to play tennis.', array['Nico played tennis.']::text[]),
  ('2bebf66b-2584-5270-8dc3-1c6bf8be0fe6', 'Busco un dueño que acepte un contrato en pesos.', 'I''m looking for a landlord who accepts a lease in pesos.', array['I''m looking for an owner who accepts a contract in pesos.', 'I''m looking for a landlord who''ll accept a lease in pesos.']::text[]),
  ('2cc71f13-2239-54fc-9f4e-005e76894611', 'Mirá el precio del queso.', 'Look at the price of cheese.', array['Look at the price of the cheese.', 'Look at how much cheese costs.']::text[]),
  ('2d3d20b0-af82-59e3-ad89-904865485c14', 'Estoy cansada porque mi bebé no está bien.', 'I''m tired because my baby isn''t well.', array['I''m tired because my baby isn''t doing well.', 'I''m tired because my baby is not well.']::text[]),
  ('2dfc375a-fd19-5fd5-b6b7-ef796a702dca', 'Por fin logré sacar la ciudadanía.', 'At last I managed to get my citizenship.', array['I finally managed to get my citizenship.', 'At last I managed to get citizenship.']::text[]),
  ('2e8c8990-2c86-5ec4-9a16-5caad320ce01', 'Mañana me levanto temprano.', 'I''m getting up early tomorrow.', array['Tomorrow I''m getting up early.', 'I get up early tomorrow.', 'I''ll get up early tomorrow.']::text[]),
  ('2ec8560c-0fc2-58bf-8e17-f1137eaf271e', 'Suspendieron las clases, así que mañana los chicos se quedan en casa.', 'They called off classes, so the kids are staying home tomorrow.', array['Classes were canceled, so the kids are staying home tomorrow.', 'They suspended classes, so tomorrow the kids stay home.']::text[]),
  ('2eeecebe-455d-53ce-91d8-d28daef9279e', 'El sábado que viene viajamos a Córdoba.', 'Next Saturday we''re traveling to Córdoba.', array['Next Saturday we travel to Córdoba.', 'We''re traveling to Córdoba next Saturday.']::text[]),
  ('2f2d1753-f576-514e-8957-2c3ead86eeae', 'Estimada Elena: ¿hay un puesto disponible en la empresa?', 'Dear Elena: is there a position available at the company?', array['Dear Elena: is there a job available at the company?', 'Dear Elena, is there a position open at the company?']::text[]),
  ('2f3b4f5b-2e0d-5bca-932b-ca23af4190e9', 'Voy un toque al kiosco.', 'I''m going to the kiosco for a second.', array['I''m going to the kiosco for a sec.', 'I''m popping out to the kiosco.']::text[]),
  ('2f740bb8-f707-5603-887b-c6b753cca284', 'El veintinueve comemos ñoquis.', 'On the twenty-ninth we eat gnocchi.', array['On the twenty-ninth we have gnocchi.', 'We eat gnocchi on the twenty-ninth.']::text[]),
  ('30069301-35a4-5b83-be45-d9c38b2d6be5', 'A mi abuela se le cayó el helado.', 'My grandmother dropped her ice cream.', array['My grandma dropped her ice cream.']::text[]),
  ('301dbdba-b640-5afd-aa4e-21ef0b8925cd', 'Las fiestas son un estrés.', 'The holidays are stressful.', array['The holidays are a stress.', 'The holidays are so stressful.']::text[]),
  ('30d24dc6-82f9-5bda-90d2-9142e1d45c2e', 'Recorrimos el sur en micro.', 'We traveled around the south by bus.', array['We toured the south by bus.', 'We traveled around the south by coach.']::text[]),
  ('3103e23f-5612-51ea-becd-6e383961874e', 'Encantada. Soy una amiga italiana de Pablo.', 'Nice to meet you. I''m an Italian friend of Pablo''s.', array['Pleased to meet you. I''m an Italian friend of Pablo''s.', 'Nice to meet you. I''m an Italian friend of Pablo.']::text[]),
  ('310a4b86-309b-5b24-8606-d8cdd1fd23d1', 'Che, estoy harto de los mails del laburo.', 'Hey, I''m fed up with work emails.', array['Hey, I''m sick of work emails.', 'Hey, I''m tired of the emails from work.']::text[]),
  ('31f0fe3e-df35-57b1-bbff-b2600b585712', 'Mi hermana se llama Juli y es estudiante.', 'My sister''s name is Juli and she''s a student.', array['My sister is called Juli and she''s a student.', 'My sister''s name is Juli and she is a student.']::text[]),
  ('32346874-c058-5066-85de-87bbe03b078d', '—¿El rojo o el de la vidriera? —Como quieras.', '—The red one or the one in the window? —Whatever you like.', array['The red one or the one in the window? As you like.', 'The red one or the one in the window? Whichever you want.']::text[]),
  ('339ec394-0fdc-58ba-aa22-79345190e2ba', '¿Se fue Rocío? Todavía no había comido.', 'Did Rocío leave? She hadn''t eaten yet.', array['Has Rocío left? She hadn''t eaten yet.', 'Rocío left? She hadn''t eaten yet.']::text[]),
  ('33bfb679-3431-54c4-b4b3-013359cbcd64', 'Este cantito lo sabe todo el estadio.', 'The whole stadium knows this chant.', array['The whole stadium knows this song.', 'Everyone in the stadium knows this chant.']::text[]),
  ('352bab6b-8fe5-52d7-9864-021a39e21161', '¿Los análisis salieron mal? Lo siento.', 'The tests came back bad? I''m sorry.', array['Did the tests come back bad? I''m sorry.', 'The test results were bad? I''m sorry.']::text[]),
  ('359a7e44-6235-5665-a362-34bd5b1014ba', 'Buenas tardes, doña Elena.', 'Good afternoon, Doña Elena.', array['Good afternoon, Mrs. Elena.']::text[]),
  ('36270fdb-62e1-52c6-ac85-2a14005bf282', 'Tomábamos helado todos los días.', 'We had ice cream every day.', array['We ate ice cream every day.', 'We used to have ice cream every day.']::text[]),
  ('363f9239-b5f0-5950-a7f5-db756431c8c9', '¿La oficina está en el segundo?', 'Is the office on the second floor?', array['Is the office on the second?']::text[]),
  ('38ff9620-dc66-5dd3-8965-dd6da71245f7', 'Metí la pata: le dije a Sofi que no me gustaba su novio.', 'I messed up: I told Sofi I didn''t like her boyfriend.', array['I screwed up: I told Sofi I didn''t like her boyfriend.', 'I put my foot in it: I told Sofi that I didn''t like her boyfriend.']::text[]),
  ('39168fc2-e584-571a-a445-d062c790ca05', 'Para mi jefa todo es urgente.', 'For my boss everything is urgent.', array['To my boss, everything is urgent.', 'Everything is urgent for my boss.']::text[]),
  ('39e51324-5814-518a-83ee-949f4d6f06c3', 'Mis hijos están llenos y tienen sueño.', 'My kids are full and sleepy.', array['My kids are full and they''re sleepy.', 'My children are full and sleepy.']::text[]),
  ('39f4adb1-0dad-5377-91e7-4a2f37367873', '—¿Listo? —Listo.', '—Ready? —Ready.', array['Ready? Done.', 'All set? All set.']::text[]),
  ('3a4680d3-2354-508f-b709-1288e029d913', 'Conocí a mis vecinos en el asado del edificio.', 'I met my neighbors at the asado in our building.', array['I met my neighbors at the building''s asado.', 'I met my neighbors at the building barbecue.']::text[]),
  ('3a6936f4-8d48-5039-a01d-3c440024f2ac', 'Mi novio se llama Santi, es de zona sur.', 'My boyfriend''s name is Santi, he''s from the southern suburbs.', array['My boyfriend is called Santi, he''s from the south side.']::text[]),
  ('3bf2acf4-5cf0-5585-97a3-d3db3c847664', '—¿Cómo es tu jefe? —Re simpático.', '—What''s your boss like? —Really friendly.', array['What is your boss like? Really nice.', 'What''s your boss like? Super friendly.']::text[]),
  ('3cad4a3c-c00b-5a4b-a2b7-d50d9ba64cfd', 'No, todavía no lo confirmó nadie.', 'No, nobody has confirmed it yet.', array['No, no one has confirmed it yet.', 'No, nobody confirmed it yet.']::text[]),
  ('3cefa5d2-5a75-5dc8-b768-30eb5ab94b32', 'Cuando se fue tu hermano a España, lloraste toda la noche.', 'When your brother left for Spain, you cried all night.', array['When your brother went to Spain, you cried all night.', 'When your brother left for Spain, you cried the whole night.']::text[]),
  ('3d42b4eb-17f9-5cba-abe9-1d23646db99e', 'Mi profesor de inglés también labura en una oficina.', 'My English teacher also works in an office.', array['My English teacher works in an office too.']::text[]),
  ('3d7708d2-1935-5750-aeb4-28da90ee0944', 'Estoy contenta, pero medio nerviosa.', 'I''m happy, but kind of nervous.', array['I''m happy, but a bit nervous.', 'I''m glad, but kind of nervous.']::text[]),
  ('3e78286f-f401-5f26-9a28-82f70147aa5b', '¿Dónde está la moza?', 'Where is the waitress?', array['Where''s the waitress?']::text[]),
  ('3ee993e8-ab2e-5fed-b606-1e02d3a909a3', 'Todo iba bien y, de golpe, me echaron.', 'Everything was going fine and, all of a sudden, they fired me.', array['Everything was going well and, suddenly, they fired me.', 'Everything was going fine and all of a sudden I got fired.']::text[]),
  ('3f04c32c-690b-56b1-abc5-a4e979c64239', 'Che, ¿cenás conmigo? Hay empanadas.', 'Hey, will you have dinner with me? There are empanadas.', array['Hey, are you having dinner with me? There are empanadas.', 'Hey, want to have dinner with me? There are empanadas.']::text[]),
  ('3f078ef6-f6f8-548b-bdd1-dcfdf7ab7003', 'En la final hincho por el cuadro de mi novia.', 'In the final I''m supporting my girlfriend''s team.', array['In the final I''m rooting for my girlfriend''s team.', 'In the final I root for my girlfriend''s team.']::text[]),
  ('40081255-7571-5fab-88c0-d92f277f9508', '—¿Belén está ahí? —No, está en Montevideo.', '—Is Belén there? —No, she''s in Montevideo.', array['Is Belén there? No, she is in Montevideo.']::text[]),
  ('40d0f413-cf22-511d-8204-f4d2e81285e8', 'Vi al ladrón y corrí para el otro lado.', 'I saw the thief and ran the other way.', array['I saw the thief and I ran the other way.', 'I saw the robber and ran in the other direction.']::text[]),
  ('41067fd9-53bb-520b-9143-a7621ee66306', '—¿Vamos al boliche? —No, odio bailar.', '—Want to go to the nightclub? —No, I hate dancing.', array['Shall we go to the club? No, I hate dancing.', 'Should we go to the nightclub? No, I hate to dance.']::text[]),
  ('428c7dc1-63b8-5838-a879-0a5ffaf3835d', '¿Adónde ibas de vacaciones?', 'Where did you use to go on vacation?', array['Where did you go on vacation?', 'Where did you used to go on vacation?']::text[]),
  ('43e156ba-23c2-5e14-849f-86e2be81daf8', 'Es pan de ayer, pero dale que va.', 'It''s yesterday''s bread, but it''s good enough.', array['It''s yesterday''s bread, but it''ll do.', 'It''s bread from yesterday, but it''s good enough.']::text[]),
  ('444b4595-49ef-537e-a964-c22bf9f98fdd', '¿La Plata está lejos de acá?', 'Is La Plata far from here?', array['Is La Plata a long way from here?']::text[]),
  ('44617375-bc54-58e8-af1a-15bf825ead60', 'Vení al balcón para que veas cómo llueve.', 'Come to the balcony so you can see how hard it''s raining.', array['Come out to the balcony so you can see how it''s raining.', 'Come to the balcony to see how hard it''s raining.']::text[]),
  ('45a80b2f-4803-5d0b-8024-a62b20d7ef48', 'Si hubiéramos tomado un taxi, no hubiéramos perdido el vuelo.', 'If we had taken a taxi, we wouldn''t have missed the flight.', array['If we''d taken a taxi, we wouldn''t have missed the flight.', 'If we had taken a cab, we wouldn''t have missed the flight.']::text[]),
  ('46445095-c6f3-54dc-862a-8d5dc9dfa46c', 'Mi ídolo volvió al club.', 'My idol came back to the club.', array['My idol returned to the club.', 'My hero came back to the club.']::text[]),
  ('464ce63e-7c68-59cd-bb0a-2a98cdcb7d12', '—¿Y Diego? —No pudo, tuvo que laburar.', '—What about Diego? —He couldn''t, he had to work.', array['And Diego? He couldn''t, he had to work.', 'What about Diego? He couldn''t make it, he had to work.']::text[]),
  ('471af026-cb9e-5757-a18e-7e4d72cbe961', '—¿Por qué estás colorado? —Me dio vergüenza.', '—Why are you red? —I felt embarrassed.', array['Why are you blushing? I got embarrassed.', 'Why are you red? I was embarrassed.']::text[]),
  ('4792b413-9115-5eb9-a956-ae5a43c59424', 'En enero viajamos a Mar del Plata, ¿venís?', 'We''re traveling to Mar del Plata in January, are you coming?', array['In January we''re traveling to Mar del Plata, are you coming?', 'We''re going to Mar del Plata in January, are you coming?']::text[]),
  ('4819026b-a656-5541-9594-555421476596', 'Mi sobrino tiene doce años.', 'My nephew is twelve.', array['My nephew is twelve years old.']::text[]),
  ('485ec68e-6ba2-5b11-9bd2-8d18bde75c54', '¿Podés traer hielo?', 'Can you bring ice?', array['Can you bring some ice?', 'Could you bring ice?']::text[]),
  ('48e9d300-babe-526a-b4c7-bc9d5fd9bcf5', '¿Tiene cinco años?', 'Is he five?', array['Is she five?', 'Is he five years old?']::text[]),
  ('48f6348d-f34b-563f-a583-581a547ad942', '—¿Entendés ahora? —Sí, me cayó la ficha.', '—Do you understand now? —Yes, I finally understood.', array['Do you get it now? Yes, it finally clicked.', 'Do you understand now? Yes, it sank in.']::text[]),
  ('49274cc1-a0a6-562c-9047-0604a139339a', 'Juan sabe un poco de inglés.', 'Juan knows a little English.', array['Juan knows a bit of English.', 'Juan knows some English.']::text[]),
  ('4ba3947e-efa4-5882-b79d-c643bce9ea00', 'Esas fotos no se las muestro a nadie.', 'I don''t show those photos to anyone.', array['I don''t show those pictures to anyone.', 'I''m not showing those photos to anybody.']::text[]),
  ('4c87376f-cfbf-5495-8157-19bfe1dd6dab', '¿A nombre de Martín?', 'Under the name Martín?', array['In Martín''s name?', 'Under Martín''s name?']::text[]),
  ('4cd50223-06ed-5aaa-9e21-688e453708b3', 'Si Mica no se hubiera ido, ¿dónde estaría a esta altura?', 'If Mica hadn''t left, where would she be by now?', array['If Mica hadn''t left, where would she be at this point?', 'If Mica had not left, where would she be by now?']::text[]),
  ('4cdd4003-f8cd-563e-9c15-20c361ff0bbe', '¿Cuántos paquetes de fideos necesitamos?', 'How many packs of pasta do we need?', array['How many packages of pasta do we need?', 'How many packs of noodles do we need?']::text[]),
  ('4cf7c45a-f7a4-528b-b18e-816b39bd8d98', 'En este edificio no se puede fumar.', 'You can''t smoke in this building.', array['Smoking isn''t allowed in this building.', 'You''re not allowed to smoke in this building.']::text[]),
  ('4ebf501c-e855-5ddf-8539-65464e5d4cae', 'Necesito un huevo, ¿tenés?', 'I need an egg, do you have one?', array['I need an egg, do you have any?', 'I need an egg, have you got one?']::text[]),
  ('4f975aa9-11c2-5ce1-8619-a55fcaf0b640', 'Mi hija tiene cinco años y mi hijo, ocho.', 'My daughter is five and my son is eight.', array['My daughter is five and my son, eight.', 'My daughter is five years old and my son is eight.']::text[]),
  ('4fd37520-2ed4-5ba8-b342-a02b63c16ece', 'Doña Marta atiende la panadería desde hace años.', 'Doña Marta has run the bakery for years.', array['Doña Marta has been running the bakery for years.', 'Doña Marta has worked at the bakery for years.']::text[]),
  ('5124fc8d-aab2-5a3f-8abe-3908128e6f22', 'Llovía y así y todo salí.', 'It was raining and even so I went out.', array['It was raining and I went out anyway.', 'It was raining and I still went out.']::text[]),
  ('51b94a05-b18e-533d-8d9c-444c4dfd2432', 'Nico llegó tarde y además no trajo nada.', 'Nico showed up late, and on top of that he didn''t bring anything.', array['Nico arrived late and, besides, he didn''t bring anything.', 'Nico came late and on top of that he brought nothing.']::text[]),
  ('51bbdffa-8724-5792-8f14-b5309ec1cf11', 'Pago las expensas por transferencia.', 'I pay the building fees by transfer.', array['I pay the building fees by bank transfer.', 'I pay the maintenance fees by transfer.']::text[]),
  ('51d7e235-0ee6-53db-8c74-ee322f194212', 'Primero hice un café y después salí con Fede.', 'First I made a coffee and then I went out with Fede.', array['First I made coffee and then I went out with Fede.', 'First I made a coffee and afterwards I went out with Fede.']::text[]),
  ('52fce698-4969-5c2c-b513-7f3f60e6f803', 'El bondi tardó una hora y así y todo llegué a tiempo.', 'The bus took an hour and even so I got there on time.', array['The bus took an hour and I still got there on time.', 'The bus took an hour and even so I arrived on time.']::text[]),
  ('53250aa6-dcf2-5f5c-b4ef-29c8bd4afda4', 'Le regalé un vino a Mati.', 'I gave Mati a bottle of wine.', array['I gave Mati a wine.', 'I gave a bottle of wine to Mati.']::text[]),
  ('537c018c-461f-5754-ab86-88d36710d1c4', 'Cuidado con el celu, que puede pasar un motochorro.', 'Watch your phone, a thief on a motorbike could come by.', array['Be careful with your phone, a motorbike thief could come by.', 'Watch your phone, a thief on a motorcycle might come by.']::text[]),
  ('53ff70a9-f7ee-53fb-a93c-cd61968bcfcd', '—¿Y el viaje? —Me quedé con las ganas.', '—And the trip? —I wanted to go, but I couldn''t.', array['And the trip? I really wanted to go, but I couldn''t.', 'What about the trip? I didn''t get to go.']::text[]),
  ('5448a268-383d-56cd-ba75-760d3350a9fb', '¿Ahora comés menos carne?', 'Are you eating less meat now?', array['Do you eat less meat now?', 'Are you eating less meat these days?']::text[]),
  ('555b6104-dacf-5138-927b-2bcfce3e6236', 'Si pagás por transferencia, te hago un descuento.', 'If you pay by transfer, I''ll give you a discount.', array['If you pay by bank transfer, I''ll give you a discount.']::text[]),
  ('557167c0-a0e7-56d7-8287-ba27a68a9813', 'Si hubiéramos ido al recital, hoy estaríamos re cansados.', 'If we had gone to the concert, we''d be really tired today.', array['If we''d gone to the concert, we''d be really tired today.', 'If we had gone to the show, we would be really tired today.']::text[]),
  ('559f90e1-5a78-565e-80d3-e294fbd1b8c7', 'Abrí la ventana sin que se escape el gato.', 'Open the window without the cat getting out.', array['Open the window without letting the cat out.', 'Open the window without the cat escaping.']::text[]),
  ('55ef31e5-c00c-5156-bfff-5d2d08d9a79f', 'No veo bien sin anteojos.', 'I can''t see well without my glasses.', array['I don''t see well without glasses.', 'I can''t see well without glasses.']::text[]),
  ('56c40017-86c4-5f16-9104-bb5c07dcaa6f', 'De a poco voy conociendo la ciudad.', 'Little by little, I''m getting to know the city.', array['I''m getting to know the city little by little.', 'Bit by bit, I''m getting to know the city.']::text[]),
  ('56f9a59e-8753-5aaa-bc4b-e9d189170ea5', '¿Tenés un kiosco? ¡Genial!', 'You have a kiosco? Awesome!', array['You have a kiosco? Great!', 'Do you have a kiosco? Awesome!']::text[]),
  ('57819dc1-8fde-5bd9-be26-0d469ce14f64', 'Fui a Mendoza de vacaciones y me enamoré de la ciudad.', 'I went to Mendoza on vacation and fell in love with the city.', array['I went to Mendoza on vacation and I fell in love with the city.', 'I went on vacation to Mendoza and fell in love with the city.']::text[]),
  ('5848e977-9666-5eb1-abdc-194590eabc3d', '—¿Fuiste al recital? —No, me quedé con las ganas.', '—Did you go to the concert? —No, I wanted to, but I couldn''t.', array['Did you go to the concert? No, I wanted to but couldn''t.', 'Did you go to the show? No, I really wanted to, but I couldn''t.']::text[]),
  ('58590334-0e0f-5613-9664-7c4451f402db', 'Che, ¿sos extranjero?', 'Hey, are you a foreigner?', array['Hey, are you foreign?', 'Hey, are you from abroad?']::text[]),
  ('58ae0830-cd0d-56ed-9d3d-7783aad528ab', '¿Esta porción es de muzza?', 'Is this slice mozzarella?', array['Is this slice cheese?', 'Is this a mozzarella slice?']::text[]),
  ('59d16331-fee1-5543-a774-fe2e5bba12c9', 'Leí en el diario que el lunes empieza la medida de fuerza.', 'I read in the newspaper that the strike starts Monday.', array['I read in the paper that the strike starts on Monday.', 'I read in the newspaper that the strike begins Monday.']::text[]),
  ('5a405fcd-7970-5bfa-b954-46a81269fed5', 'Hace años que doña Susana vive en este edificio.', 'Doña Susana has lived in this building for years.', array['Doña Susana has been living in this building for years.', 'Mrs. Susana has lived in this building for years.']::text[]),
  ('5ae47a7b-6613-5aa6-ac3f-c8b26226058d', 'Me da vergüenza, pero hablar de eso me hace bien.', 'I feel embarrassed, but talking about it does me good.', array['I''m embarrassed, but talking about it does me good.', 'It embarrasses me, but talking about it is good for me.']::text[]),
  ('5c3427e3-ab8b-51e8-8729-51d5865f75f7', 'Me duele acá, en la mano.', 'It hurts here, in my hand.', array['It hurts here, on my hand.', 'My hand hurts, here.']::text[]),
  ('5e9a1e94-19db-5069-a805-4d74117bf95f', 'El tren está lleno, ¿tomamos un taxi?', 'The train is packed, should we take a taxi?', array['The train is full, should we take a taxi?', 'The train is packed, shall we take a cab?']::text[]),
  ('6050601b-c839-5620-a2f0-cd600b0e56ea', 'La empresa dice que este año paga el aguinaldo en cuotas.', 'The company says it''s paying the bonus in installments this year.', array['The company says that this year it''s paying the bonus in installments.', 'The company says it will pay the bonus in installments this year.']::text[]),
  ('60d03702-a07c-5037-a2af-ae9eb971a198', '—¿Te gusta la verdura? —Más o menos.', '—Do you like vegetables? —So-so.', array['Do you like vegetables? More or less.', 'Do you like vegetables? Kind of.']::text[]),
  ('60dfcf99-1a62-54fc-9089-f6ef51a97450', '—¿Hasta cuándo tenemos plazo? —Hasta el viernes.', '—When is our deadline? —Friday.', array['When''s our deadline? Friday.', 'How long do we have? Until Friday.']::text[]),
  ('61d042b1-3401-56b6-b764-fc0ffb5cb0d7', 'Dicen que hay un motochorro en el barrio.', 'They say there''s a thief on a motorbike in the neighborhood.', array['They say there''s a motorbike thief in the neighborhood.', 'People say there''s a thief on a motorcycle in the neighborhood.']::text[]),
  ('626b4a31-c275-59f1-a71b-1b01e6be459c', 'Está cerca del laburo; por otro lado, me parece chico.', 'It''s close to work; on the other hand, I think it''s small.', array['It''s near work; on the other hand, it seems small to me.', 'It''s close to work; then again, I think it''s small.']::text[]),
  ('628bb1cd-cffa-5c6e-83c9-dbc415231c5e', 'Me dio angustia cuando vi la cuenta de luz.', 'I got upset when I saw the electricity bill.', array['I got anxious when I saw the electricity bill.', 'I felt upset when I saw the electric bill.']::text[]),
  ('63115c6c-3e96-5c18-bf00-382348e031d5', 'Mi cuñado está medio agrandado desde que tiene plata.', 'My brother-in-law has been kind of arrogant since he got money.', array['My brother-in-law has been kind of full of himself since he got money.', 'My brother-in-law has been a bit arrogant ever since he has money.']::text[]),
  ('63b2934b-5db1-5e84-96e3-749df1336a00', 'El trámite demoró un montón y llegué tarde al laburo.', 'The process took a really long time and I was late for work.', array['The paperwork took forever and I was late for work.', 'The process took a long time and I got to work late.']::text[]),
  ('65881c38-4261-51e2-a7dd-b1db1cfa2736', '—¿Tu jefa es simpática? —Más o menos.', '—Is your boss friendly? —Sort of.', array['Is your boss nice? Kind of.', 'Is your boss friendly? More or less.']::text[]),
  ('6701c823-05c5-511c-86d4-ed771d5e2f1a', 'Me enteré del rumor por el grupo de WhatsApp.', 'I found out about the rumor in the WhatsApp group.', array['I heard about the rumor in the WhatsApp group.', 'I found out about the rumor through the WhatsApp group.']::text[]),
  ('677fdf56-8f4f-597d-9911-6f260c8ca46c', 'Entiendo poco. ¿Me repetís más despacio?', 'I understand very little. Can you repeat that more slowly?', array['I understand very little. Can you say that again more slowly?', 'I don''t understand much. Can you repeat that more slowly?']::text[]),
  ('68a7d8ba-d76b-56cc-b19d-098276e01605', 'Es mejor que salgamos temprano.', 'It''s better if we leave early.', array['It''s better that we leave early.', 'We''d better leave early.']::text[]),
  ('68d55bb4-d3e2-5587-86aa-ace06aebcbb0', 'Mica está re segura de lo que dice.', 'Mica is really sure of what she''s saying.', array['Mica is very sure of what she''s saying.', 'Mica is really sure about what she says.']::text[]),
  ('69f3c1f8-1d32-5a04-94c8-1b8b77abdd84', '¿Hoy juega Brasil?', 'Is Brazil playing today?', array['Does Brazil play today?']::text[]),
  ('69f778b2-bc33-5e9d-bf9e-b7537ac7a5a4', 'Esta remera roja es muy linda, pero está rota.', 'This red T-shirt is very nice, but it''s torn.', array['This red T-shirt is very pretty, but it''s ripped.', 'This red shirt is very nice, but it''s torn.']::text[]),
  ('6a252d1e-d8b5-571b-a73e-5571c4871c70', 'A vos te encanta el fútbol, a mí no.', 'You love soccer, I don''t.', array['You love soccer, not me.']::text[]),
  ('6aee442e-0a55-5e3b-93fd-a3a3ca6ac97d', 'Al principio me costó entender a la gente.', 'At first it was hard for me to understand people.', array['At first I had a hard time understanding people.', 'In the beginning it was hard for me to understand people.']::text[]),
  ('6b488aa3-b86b-5165-b2c3-fde03a2b44cf', 'La cuota del auto es muy alta.', 'The car installment is very high.', array['The car payment is very high.', 'The car installment is really high.']::text[]),
  ('6b6d66a5-d2b0-5ad8-b474-e9a7b0a55181', 'Escuché un ruido y corrí a la puerta.', 'I heard a noise and ran to the door.', array['I heard a noise and I ran to the door.']::text[]),
  ('6bb65fde-4e7d-547c-b9c9-6d07a9e7f3de', 'Le contesté a Juli que no puedo ir al cine.', 'I told Juli I can''t go to the movies.', array['I answered Juli that I can''t go to the movies.', 'I told Juli that I can''t go to the movies.']::text[]),
  ('6c62e85d-ae29-51a9-8dec-b8d13557df6c', '¿Te bañás ahora o después?', 'Are you showering now or later?', array['Are you taking a shower now or later?', 'Will you shower now or later?']::text[]),
  ('6c818f7f-0975-592d-937d-f9f90fb761cf', 'Mucha gente en Buenos Aires tiene raíces en Europa.', 'A lot of people in Buenos Aires have roots in Europe.', array['Many people in Buenos Aires have roots in Europe.', 'Lots of people in Buenos Aires have European roots.']::text[]),
  ('6cdd005a-80b9-5d43-a7e0-86dc937c1af0', 'Sacamos una foto cada kilómetro.', 'We took a photo every kilometer.', array['We took a picture every kilometer.', 'We took a photo each kilometer.']::text[]),
  ('6d1b0a3a-2b98-5a6a-a361-abd23f1eac9c', '—¿Todo bien? —No, mal.', '—All good? —No, not good.', array['Everything okay? No, bad.', 'All good? No, bad.']::text[]),
  ('6d2485c5-9fb6-5895-8c6c-f392b5f61df7', 'Tengo mucho estrés por el examen.', 'I''m under a lot of stress because of the exam.', array['I''m very stressed about the exam.', 'I''m really stressed because of the exam.']::text[]),
  ('6d808a78-4b51-5e08-a8e2-ca55a928b2f0', 'Vos hinchás por Brasil y yo por Argentina.', 'You support Brazil and I support Argentina.', array['You root for Brazil and I root for Argentina.', 'You''re for Brazil and I''m for Argentina.']::text[]),
  ('6da6bdd9-5ced-516a-9abc-190c7ddabb0f', 'Prefiero que Pablo no sepa nada.', 'I''d rather Pablo didn''t know anything.', array['I prefer that Pablo doesn''t know anything.', 'I''d rather Pablo not know anything.']::text[]),
  ('6ea62cfd-a85b-500f-83b4-46026a765098', 'Don Carlos atiende el almacén de la esquina.', 'Don Carlos runs the corner store.', array['Don Carlos runs the store on the corner.', 'Don Carlos works at the corner store.']::text[]),
  ('6f72c04c-44cc-5da5-abf0-20d25b6ca402', '¿Tu vecino tiene tus paquetes?', 'Does your neighbor have your packages?', array['Does your neighbor have your parcels?']::text[]),
  ('6fcbb6b4-2788-5423-903f-8320883dc17d', 'Estimada Susana: gracias por la reunión de ayer.', 'Dear Susana: thanks for yesterday''s meeting.', array['Dear Susana: thank you for yesterday''s meeting.', 'Dear Susana, thanks for the meeting yesterday.']::text[]),
  ('70abd993-1f9b-5aff-a0a5-66e5212781a2', 'Cuidado con mis anteojos, si no, no te presto nada más.', 'Careful with my glasses, otherwise I won''t lend you anything else.', array['Be careful with my glasses, or I won''t lend you anything else.', 'Careful with my glasses, or else I won''t lend you anything again.']::text[]),
  ('711d8d19-99e7-54f4-82f0-8e52f63971ea', 'Probate un talle más chico.', 'Try one size smaller.', array['Try a smaller size.', 'Try on one size smaller.']::text[]),
  ('7176d96d-74f9-50e4-9d23-03eb709a2b50', 'El auto cuesta treinta millones.', 'The car costs thirty million.', array['The car costs thirty million pesos.']::text[]),
  ('717a510d-e23d-5363-9d85-b7fe5dff6342', 'Se pelearon por una piba.', 'They had a fight over a girl.', array['They fought over a girl.', 'They got into a fight over a girl.']::text[]),
  ('71f3cb6c-0485-5f71-8672-bb9864bf35ed', '—¿Los fideos eran con tuco? —Sí, siempre con tuco.', '—Was the pasta with tomato sauce? —Yes, always with tomato sauce.', array['Did the pasta have tomato sauce? Yes, always with tomato sauce.']::text[]),
  ('72efcbb0-8fda-5bb2-9384-9166fbb9bd5f', 'A Juan lo echaron y, para colmo, se enteró por mail.', 'Juan got fired, and on top of that, he found out by email.', array['Juan was fired and, to top it off, he found out by email.', 'They fired Juan and, on top of that, he found out by email.']::text[]),
  ('731453de-b48a-58cf-9904-75e6a3d500a5', 'Este verano quiero recorrer Córdoba.', 'This summer I want to travel around Córdoba.', array['This summer I want to tour Córdoba.', 'I want to travel around Córdoba this summer.']::text[]),
  ('733ab4a3-cf83-5c0f-bf69-85fe1c3807b3', 'Este jean negro es muy caro.', 'These black jeans are very expensive.', array['This black pair of jeans is very expensive.', 'These black jeans are really expensive.']::text[]),
  ('73447b92-d791-55f9-9b55-0341032146e7', '¿Belén tiene siete años?', 'Is Belén seven?', array['Is Belén seven years old?']::text[]),
  ('73d69df9-fdf6-5ca5-bed3-d0eabe569ecf', '¿Laburás a la mañana?', 'Do you work in the morning?', array['Do you work mornings?', 'Do you work in the mornings?']::text[]),
  ('742f4317-b8dd-5362-b137-8204e29e1f80', 'El presupuesto del proyecto es de diez mil dólares.', 'The project''s budget is ten thousand dollars.', array['The budget for the project is ten thousand dollars.', 'The project budget is ten thousand dollars.']::text[]),
  ('748cc4af-7307-5f68-b877-db0c099ffbb0', 'La canilla de la cocina gotea, ¿llamás al plomero?', 'The kitchen faucet is dripping, can you call the plumber?', array['The kitchen faucet is dripping, will you call the plumber?', 'The kitchen tap is dripping, can you call the plumber?']::text[]),
  ('74ae9e0e-ea17-5656-97ec-3bcb3bd94531', 'El alquiler aumenta cada tres meses.', 'Rent goes up every three months.', array['The rent goes up every three months.', 'Rent increases every three months.']::text[]),
  ('74e1f5f8-e358-5cbe-9712-46e11953a390', '—¿Qué estudiás en la facu? —Inglés.', '—What do you study at college? —English.', array['What do you study in college? English.', 'What are you studying at college? English.']::text[]),
  ('75ecaa1b-ee26-5f5f-acda-29f60d1f2749', '¡Cuidado, que se te vuela la gorra!', 'Careful, your cap is going to blow away!', array['Watch out, your cap is going to fly off!', 'Careful, your cap''s going to blow away!']::text[]),
  ('78a2438b-e95b-537d-8607-d8a10da2a023', '¿Me prestás el celu un momento?', 'Can you lend me your phone for a moment?', array['Can I borrow your phone for a moment?', 'Can you lend me your phone for a second?']::text[]),
  ('79b7d41f-e717-5eba-a5e6-6fdb3a19ef37', 'Te pedí que hicieras la cama.', 'I asked you to make the bed.', array['I asked you to make your bed.']::text[]),
  ('79f180bb-038e-5afc-9227-0b23823cf668', 'No, mi hija no tiene once, tiene doce.', 'No, my daughter isn''t eleven, she''s twelve.', array['No, my daughter isn''t eleven, she is twelve.', 'No, my daughter''s not eleven, she''s twelve.']::text[]),
  ('7bb150a2-7cc5-5ee0-84d5-37f6072d8838', 'Si no podés ir, ¿me avisás?', 'If you can''t go, will you let me know?', array['If you can''t go, can you let me know?', 'If you can''t go, will you tell me?']::text[]),
  ('7c2fc90f-4f4d-5402-87d5-938764285db0', 'Te cuento cómo fue la charla con Lucía.', 'I''ll tell you how the chat with Lucía went.', array['I''ll tell you how the talk with Lucía went.', 'I''ll tell you how the conversation with Lucía went.']::text[]),
  ('7d302d96-e475-5f82-ab0a-4189e1ad56ec', '—¿Pagás vos? —Ni a palos.', '—Are you paying? —No way.', array['Are you paying? Not a chance.']::text[]),
  ('7d642b12-68da-5acc-896a-42f0a6dd320b', 'Cami aclaró que no la esperáramos.', 'Cami made it clear we shouldn''t wait for her.', array['Cami made it clear that we shouldn''t wait for her.', 'Cami made it clear not to wait for her.']::text[]),
  ('7df13d12-12e7-52f2-8673-cdbdf0535ae4', 'Con gusto te muestro el depto.', 'I''d be happy to show you the apartment.', array['I''ll gladly show you the apartment.', 'I''d be glad to show you the apartment.']::text[]),
  ('7df6c4e9-e169-5fda-a441-5ece5ef7269b', '¿Ya estás jubilado? ¡Qué bueno!', 'You''re already retired? That''s great!', array['Are you retired already? That''s great!', 'You''re already retired? How nice!']::text[]),
  ('7e0b8fef-8fbc-5457-8c1f-d2a1a225d51b', '—¿Me cuidás el perro? —¡Cómo no!', '—Will you watch my dog? —Of course!', array['Will you look after my dog? Of course!', 'Can you watch my dog? Sure!']::text[]),
  ('7e0b9484-7c41-56ce-99e8-fb3d1609777c', 'Permiso, gracias.', 'Excuse me, thanks.', array['Excuse me, thank you.']::text[]),
  ('7e1cd8fe-d31b-5b24-87f9-11d07a1f9a96', 'Perdón, el vaso está sucio, ¿me traés otro?', 'Excuse me, the glass is dirty, can you bring me another one?', array['Sorry, the glass is dirty, can you bring me another?', 'Excuse me, the glass is dirty, could you bring me another one?']::text[]),
  ('7f0a089e-5f3e-5a99-9400-4d7f16fecd31', 'Papá quería que hicieras las compras.', 'Dad wanted you to do the shopping.', array['Dad wanted you to go shopping.', 'Dad wanted you to do the grocery shopping.']::text[]),
  ('7f56d42c-4b21-56ae-ae67-9056a1bb5b97', '¿Sabés más chistes? Dale, contame otro.', 'Do you know more jokes? Come on, tell me another one.', array['Do you know any more jokes? Come on, tell me another.', 'Do you know more jokes? Go on, tell me another one.']::text[]),
  ('800b9178-80e5-55c6-b714-98e82e4092be', '—¿Tu abuelo está orgulloso de vos? —Sí, un montón.', '—Is your grandfather proud of you? —Yes, really proud.', array['Is your grandpa proud of you? Yes, very.', 'Is your grandfather proud of you? Yes, a lot.']::text[]),
  ('8025cdf1-e014-5988-bbde-578a5bc8723b', '—¿Dónde es el corte? —En la avenida.', '—Where''s the road closure? —On the avenue.', array['Where is the roadblock? On the avenue.', 'Where''s the road closed? On the avenue.']::text[]),
  ('8060970f-f0be-5b5a-9b3b-1e553a078833', '¿Pagás las expensas en efectivo o por transferencia?', 'Do you pay the building fees in cash or by transfer?', array['Do you pay the building fees in cash or by bank transfer?', 'Do you pay the maintenance fees in cash or by transfer?']::text[]),
  ('809f69d0-3ce5-5d64-b111-c23a667d359a', 'La moza tiene el café de Nico.', 'The waitress has Nico''s coffee.', array['The server has Nico''s coffee.']::text[]),
  ('80bf2339-b47b-5c1d-aab0-eda9d9d2cd8e', 'El desayuno fue lo mejor del hotel.', 'Breakfast was the best part of the hotel.', array['The breakfast was the best thing about the hotel.', 'Breakfast was the best thing at the hotel.']::text[]),
  ('8210b6ed-fd34-5ccc-9b7f-2f211a841f76', 'Estimada Marta: te envié mi CV.', 'Dear Marta: I sent you my CV.', array['Dear Marta: I sent you my résumé.']::text[]),
  ('821f40d0-3954-53c9-a1de-f0bc63ac6a1f', 'Voté en Rosario porque mi DNI todavía tiene la dirección de allá.', 'I voted in Rosario because my ID still has my address there.', array['I voted in Rosario because my ID still has the address from there.', 'I voted in Rosario because my ID still shows my address there.']::text[]),
  ('8293bb64-73cf-5f99-89be-389eca89da1e', '—¿Cómo es su novio? —Lindo, pero no es simpático.', '—What''s her boyfriend like? —Good-looking, but not friendly.', array['What is her boyfriend like? Handsome, but not friendly.', 'What''s his boyfriend like? Good-looking, but he isn''t nice.']::text[]),
  ('82dac744-a2dd-5890-af19-3692e3218af2', '¡Qué lindos son tus gatos!', 'Your cats are so cute!', array['How cute your cats are!', 'Your cats are so pretty!']::text[]),
  ('835a5f3e-49f5-5d2e-9f2c-5679815a75e3', 'Me hubiera gustado venir antes.', 'I would have liked to come sooner.', array['I would''ve liked to come earlier.', 'I''d have liked to come sooner.']::text[]),
  ('84672825-ad15-5c37-9004-041a641284fa', 'Te presto la bici, salvo que la necesite yo.', 'I''ll lend you the bike, unless I need it.', array['I''ll lend you my bike, unless I need it.', 'I''ll lend you the bike unless I need it myself.']::text[]),
  ('84cb7f7d-3154-5093-9ec5-eceef83c99d3', '¿Quién trajo el postre?', 'Who brought the dessert?', array['Who brought dessert?']::text[]),
  ('851b2840-fbb6-504a-98d3-fd24b03d0f7d', 'Mi hijo tiene dieciocho años y es estudiante.', 'My son is eighteen and he''s a student.', array['My son is eighteen years old and he''s a student.', 'My son is eighteen and a student.']::text[]),
  ('85fee7db-e66f-5ac1-9d26-94cd390f6e74', 'Me contestó que venía más tarde.', 'He told me he was coming later.', array['She told me she was coming later.', 'He answered that he was coming later.']::text[]),
  ('866b3534-947d-560a-b345-55cfc94bc786', 'Tranqui, sabemos llegar.', 'Relax, we know how to get there.', array['Don''t worry, we know how to get there.', 'Relax, we know the way.']::text[]),
  ('879a5d90-1cb9-5a44-80d7-c66bdff4930d', 'Bajá el video con wifi.', 'Download the video on wifi.', array['Download the video over wifi.', 'Download the video using wifi.']::text[]),
  ('87f289b5-4d0d-549f-9060-ce108f86b377', '¿Vos hinchás por Italia?', 'Do you support Italy?', array['Do you root for Italy?', 'Are you rooting for Italy?']::text[]),
  ('882df5c1-8db9-52f8-a903-2baeafc2690a', '—¿Qué toman? —Un café y un jugo, por favor.', '—What would you like to drink? —A coffee and a juice, please.', array['What will you have? A coffee and a juice, please.', 'What are you drinking? A coffee and a juice, please.']::text[]),
  ('883324a3-770f-5cb2-a370-e0aaf087ad0f', '—¿Tu hermana se la bancó? —Sí, re bien.', '—Did your sister handle it? —Yes, really well.', array['Did your sister cope with it? Yes, really well.', 'Did your sister handle it? Yeah, really well.']::text[]),
  ('899b8ce7-856b-51de-9956-10518f37bf15', 'Estaba enfermo y así y todo vino.', 'He was sick and even so he came.', array['He was sick and he came anyway.', 'She was sick and even so she came.']::text[]),
  ('8a18ed64-2bfd-5213-82b1-68bdcc10dcba', 'Ella es Juli y tiene doce años.', 'She''s Juli and she''s twelve.', array['This is Juli and she''s twelve.', 'She is Juli and she is twelve years old.']::text[]),
  ('8a4e219a-8b3d-582f-a037-d21a1a448ded', 'Mi abuela hace ñoquis para toda la familia todos los veintinueve.', 'My grandmother makes gnocchi for the whole family every twenty-ninth.', array['My grandma makes gnocchi for the whole family every twenty-ninth.', 'My grandmother makes gnocchi for the whole family on the twenty-ninth of every month.']::text[]),
  ('8bafded5-b951-5440-b603-9538700233b0', 'Mica lo dejó por WhatsApp.', 'Mica broke up with him on WhatsApp.', array['Mica dumped him over WhatsApp.', 'Mica broke up with him over WhatsApp.']::text[]),
  ('8c729b57-3db6-5ae1-bafc-66f6fe8a6768', 'Nico se mudó a dos cuadras de acá.', 'Nico moved two blocks from here.', array['Nico moved two blocks away from here.', 'Nico moved to two blocks from here.']::text[]),
  ('8d0eead0-02f0-5272-b61f-7f3d1836b967', 'En la radio dijeron que fueron detenidos.', 'On the radio they said they were arrested.', array['They said on the radio that they were arrested.', 'On the radio they said that they were detained.']::text[]),
  ('8d25ae4e-8399-588c-8fd2-64993e208961', '¿Suspendieron el examen? ¡Qué bueno!', 'They called off the exam? That''s great!', array['Did they call off the exam? That''s great!', 'They canceled the exam? Great!']::text[]),
  ('8db26f62-ed84-57fd-9e24-2fd309d5983d', 'La noche fue corta: dormí tres horas.', 'The night was short: I slept three hours.', array['It was a short night: I slept three hours.', 'The night was short: I slept for three hours.']::text[]),
  ('8e468303-6e13-5b61-ac69-413bb90546aa', 'Llenábamos el álbum del Mundial entre todos.', 'We used to fill the World Cup album together.', array['We all filled the World Cup album together.', 'We would fill the World Cup album together.']::text[]),
  ('8f031d38-7146-5330-a03f-ef1b0365a694', 'Dicen en la tele que fueron detenidos en la cancha.', 'They say on TV that they were arrested at the stadium.', array['On TV they say they were arrested at the stadium.', 'They''re saying on TV that they were detained at the stadium.']::text[]),
  ('8fe46c4d-cb4a-5570-a596-0f6117f5d152', 'Mi novia se llama Cami y es profe.', 'My girlfriend''s name is Cami and she''s a teacher.', array['My girlfriend is called Cami and she''s a teacher.', 'My girlfriend''s name is Cami and she is a teacher.']::text[]),
  ('8feabd6c-cc12-5a48-9c21-42fa374ccc10', '¿Pudiste hablar con tu jefe?', 'Were you able to talk to your boss?', array['Did you get to talk to your boss?', 'Could you talk to your boss?']::text[]),
  ('9012184b-95df-5df7-9252-d602c60ab5d2', 'Me olvidé de pagar la cuenta y me puse colorada.', 'I forgot to pay the check and turned red.', array['I forgot to pay the bill and I blushed.', 'I forgot to pay the check and went red.']::text[]),
  ('92079478-cda9-56f2-8310-4bb0dd4dbb72', 'A los chicos les encantarían unos días en la playa.', 'The kids would love a few days at the beach.', array['The kids would love a few days on the beach.', 'The children would love a few days at the beach.']::text[]),
  ('92e825c3-d10f-550a-8c5e-5d37ff1aa68b', '—¿Hace calor? —Sí, y hay mucha humedad.', '—Is it hot? —Yes, and it''s really humid.', array['Is it hot? Yes, and it''s very humid.', 'Is it hot out? Yeah, and there''s a lot of humidity.']::text[]),
  ('940aeba6-691e-55a7-8b3b-caac2b5685cc', 'No, Nico no tiene nueve, tiene diez.', 'No, Nico isn''t nine, he''s ten.', array['No, Nico isn''t nine, he is ten.', 'No, Nico''s not nine, he''s ten.']::text[]),
  ('94f714b1-36b1-577b-823d-df54dd8d8638', 'Hay un árbol re grande en la puerta de mi edificio.', 'There''s a really big tree at the door of my building.', array['There''s a huge tree at the entrance of my building.', 'There is a really big tree by the door of my building.']::text[]),
  ('951787ef-8043-5914-8ca9-a2a7f8e235b9', 'Perdón, la carta, por favor.', 'Excuse me, the menu, please.', array['Sorry, the menu, please.']::text[]),
  ('9532e835-4415-5151-8d40-2fc6ef3cc331', '—¿Puedo pasar al baño? —Faltaba más, querido.', '—Can I use the bathroom? —Of course, dear.', array['May I use the bathroom? By all means, dear.']::text[]),
  ('95b60826-8491-5948-8164-071a1b9302f1', 'Cuando se fue el ídolo del club, toda la hinchada estaba triste.', 'When the club''s idol left, all the fans were sad.', array['When the club''s hero left, all the supporters were sad.']::text[]),
  ('97d746f7-ca27-512a-8c6e-a5c9360a9aea', 'Me preguntó de qué estábamos hablando.', 'He asked me what we were talking about.', array['She asked me what we were talking about.']::text[]),
  ('9824bc95-6631-55de-b728-6f5ed1a24d7c', 'Mirá vos, no sabía.', 'Wow, I didn''t know.', array['Really? I didn''t know.', 'Well, look at that, I didn''t know.']::text[]),
  ('985f37c9-8a97-5230-a4ce-a3cb684e7ffb', 'Mi hija tiene siete años y mi sobrina, diez.', 'My daughter is seven and my niece is ten.', array['My daughter is seven and my niece, ten.', 'My daughter is seven years old and my niece is ten.']::text[]),
  ('989c0720-eacf-5637-bf70-ae2c470d9e0b', '—¿Cómo es Belén? —Alta, rubia y simpática.', '—What''s Belén like? —Tall, blonde, and friendly.', array['What is Belén like? Tall, blond and friendly.', 'What''s Belén like? Tall, blonde, and nice.']::text[]),
  ('996ce954-bd97-5853-8a2e-4450f2238fbc', '—¿Venís al asado? —¡Más vale!', '—Are you coming to the asado? —Of course!', array['Are you coming to the asado? You bet!', 'Are you coming to the barbecue? Of course!']::text[]),
  ('99ae3271-9281-5129-b565-feb3410e5de4', 'Anoche me pegué un susto bárbaro.', 'Last night I got a huge fright.', array['I got a terrible scare last night.', 'Last night I got a really big scare.']::text[]),
  ('9a1ab1c3-a45d-5f61-b623-33cd1d706826', 'Por más que me dé vergüenza, voy a hablar en castellano.', 'No matter how embarrassed I get, I''m going to speak Spanish.', array['Even if I''m embarrassed, I''m going to speak Spanish.', 'However embarrassed I get, I''m going to speak Spanish.']::text[]),
  ('9b9798b7-bb44-5f0b-a16a-42897f981c73', 'Don José es jubilado, pero sigue laburando.', 'Don José is retired, but he''s still working.', array['Don José is retired, but he keeps working.', 'Mr. José is retired, but he still works.']::text[]),
  ('9d3a03ab-f50b-5a4f-83a4-8f4be8238a66', 'Este mes la tarifa del gas está re alta.', 'This month the gas rate is really high.', array['The gas rate is really high this month.', 'This month the gas bill is really high.']::text[]),
  ('9d47a9cc-772c-5d8b-953d-5f01c0da5e9e', 'Ella es Marta, mi abuela.', 'She''s Marta, my grandmother.', array['This is Marta, my grandmother.', 'She''s Marta, my grandma.']::text[]),
  ('9dfe55fb-ecd7-508b-999c-30cee5f90b82', 'Anoche suspendieron el servicio por una medida de fuerza.', 'Last night they suspended the service because of a strike.', array['Last night they suspended service because of a strike.', 'Service was suspended last night due to a strike.']::text[]),
  ('9e238f28-232c-556b-83a0-ded93983e8a0', '—¿Podríamos cambiar de mesa? —Sí, con gusto.', '—Could we change tables? —Yes, with pleasure.', array['Could we switch tables? Yes, gladly.', 'Could we change tables? Yes, of course.']::text[]),
  ('9eaa25f1-e30c-5260-9cde-04cc62ad5bbc', '¿Fueron al campo en tren?', 'Did they go to the countryside by train?', array['Did you guys go to the countryside by train?', 'Did they go to the country by train?']::text[]),
  ('9eec3a45-1853-5fa2-a53f-5de917002fc5', 'No seas zarpada, es mi abuela.', 'Don''t be rude, she''s my grandmother.', array['Don''t be disrespectful, she''s my grandmother.', 'Don''t be rude, that''s my grandma.']::text[]),
  ('a26d6351-3b56-5d01-9f55-9311b7e82cf5', 'Él es mi perro.', 'He''s my dog.', array['This is my dog.', 'He is my dog.']::text[]),
  ('a2799167-5f29-5ada-a61b-6a1d0aed3467', 'Juan y Sofi empiezan la facu juntos.', 'Juan and Sofi start college together.', array['Juan and Sofi are starting college together.', 'Juan and Sofi start university together.']::text[]),
  ('a29a8fc2-9f3a-591b-939f-73138735ed26', 'Se pelean por todo.', 'They fight about everything.', array['They fight over everything.', 'They argue about everything.']::text[]),
  ('a359c6fd-4384-54a6-9382-24138da1f8c9', 'Veo a mis viejos los domingos.', 'I see my parents on Sundays.', array['I see my parents on Sunday.', 'I see my folks on Sundays.']::text[]),
  ('a488b278-379e-5fe3-9f52-1c18a634028e', 'Si hubiéramos salido temprano, ya estaríamos en casa.', 'If we had left early, we would be home by now.', array['If we''d left early, we''d already be home.', 'If we had left early, we would already be at home.']::text[]),
  ('a4cef022-f6f5-5285-9c47-da682de4780d', 'Che, ¿sos extranjera?', 'Hey, are you a foreigner?', array['Hey, are you foreign?', 'Hey, are you from abroad?']::text[]),
  ('a5cef09c-e903-51a1-a8cc-b76e39f73299', 'Hace meses que estoy buscando laburo.', 'I''ve been looking for work for months.', array['I''ve been looking for a job for months.', 'I''ve been job hunting for months.']::text[]),
  ('a7c59522-4a4b-5a22-a807-44390143efe9', 'Mi tía alquilaba en el centro, pero se mudó al campo.', 'My aunt used to rent downtown, but she moved to the country.', array['My aunt rented downtown, but she moved to the countryside.', 'My aunt used to rent in the city center, but she moved to the country.']::text[]),
  ('a84788c1-452e-5ea1-a18b-4936d9b5901b', 'La reunión fue corta, por suerte.', 'The meeting was short, luckily.', array['Luckily, the meeting was short.', 'The meeting was short, thankfully.']::text[]),
  ('a8601a48-8e72-526d-a303-877fe3eb97d5', 'Me encantarían unas zapatillas así, pero cuestan un montón.', 'I''d love some sneakers like those, but they cost a lot.', array['I would love sneakers like those, but they cost a ton.', 'I''d love a pair of sneakers like that, but they''re really expensive.']::text[]),
  ('a89a168f-e30b-5d92-b64e-d809b7d748e3', '¿Este mueble es tuyo o del dueño?', 'Is this piece of furniture yours or the landlord''s?', array['Is this furniture yours or the landlord''s?', 'Is this piece of furniture yours or the owner''s?']::text[]),
  ('a97bdaed-6148-5da9-8c15-2071b12b77de', 'Extrañaba a mi abuela y el domingo la fui a visitar.', 'I missed my grandma, and on Sunday I went to visit her.', array['I missed my grandmother and on Sunday I went to see her.', 'I was missing my grandma, and on Sunday I visited her.']::text[]),
  ('a98c3207-ba54-5732-8dcf-002afa572775', 'Desde ya, gracias por tu ayuda.', 'Thanks in advance for your help.', array['Thank you in advance for your help.', 'Thanks in advance for the help.']::text[]),
  ('aa7f47a0-b7eb-57df-9b81-55257cbf203e', 'Con el costo de vida que hay acá, no puedo ahorrar.', 'With the cost of living here, I can''t save.', array['With the cost of living here, I can''t save money.', 'With how expensive life is here, I can''t save.']::text[]),
  ('ab5bb0de-e249-5c72-8fb9-09258a185ca3', 'Habla de fútbol como si supiera un montón.', 'He talks about soccer as if he knew a lot.', array['He talks about soccer as though he knew a lot.', 'She talks about soccer as if she knew a lot.']::text[]),
  ('ab7e5f31-4433-53fe-9e96-a6ebcc2015e0', 'Juan se fue porque ya había comido.', 'Juan left because he''d already eaten.', array['Juan left because he had already eaten.']::text[]),
  ('ac24f366-605a-536d-a6c3-cb09a5c63da2', 'En vacaciones es difícil no engordar.', 'On vacation it''s hard not to put on weight.', array['It''s hard not to gain weight on vacation.', 'On vacation it''s hard not to gain weight.']::text[]),
  ('ac582a31-c0dd-5b5c-96ff-b17191255264', 'Hoy es veintinueve, hago ñoquis.', 'Today is the twenty-ninth, I''m making gnocchi.', array['Today''s the twenty-ninth, I''m making gnocchi.', 'It''s the twenty-ninth today, I''ll make gnocchi.']::text[]),
  ('ad2f9edd-840a-5f8b-b6a4-c897d2eb60f0', '—¿Qué querés tomar? —Lo que sea.', '—What do you want to drink? —Anything is fine.', array['What do you want to drink? Whatever.', 'What would you like to drink? Anything.']::text[]),
  ('ae942a90-1cb1-585c-86d3-560c43cafdf5', 'Tomá despacito, que está caliente.', 'Drink it nice and slow, it''s hot.', array['Drink it slowly, it''s hot.', 'Sip it slowly, it''s hot.']::text[]),
  ('aeed3d3a-8a44-5489-af2b-2cfd7882f18b', 'Otro gol de Brasil.', 'Another goal for Brazil.', array['Another Brazil goal.', 'Another goal by Brazil.']::text[]),
  ('afaa7572-f33e-5148-89f6-272bba31aead', 'Hacía mucho frío y así y todo fuimos a la playa.', 'It was really cold and even so we went to the beach.', array['It was very cold and we went to the beach anyway.', 'It was really cold and we still went to the beach.']::text[]),
  ('afc50da2-7864-551b-86c5-9484593544f6', 'Me anoté en el gimnasio, empiezo el lunes que viene.', 'I signed up at the gym, I start next Monday.', array['I joined the gym, I start next Monday.', 'I signed up for the gym, I''m starting next Monday.']::text[]),
  ('b0d4b3f4-7f3d-577e-b7e6-418b7363eb0c', 'Dejé una fotocopia del DNI en la oficina.', 'I left a photocopy of my ID at the office.', array['I left a copy of my ID at the office.', 'I left a photocopy of my ID in the office.']::text[]),
  ('b0d8913a-b839-518c-903a-28b5ff92a48b', '¿Cómo estuvo el recital del sábado?', 'How was Saturday''s concert?', array['How was the concert on Saturday?', 'How was Saturday''s show?']::text[]),
  ('b1853b88-2a1e-525f-88d9-16f7bfda2626', 'Perdón, pero tengo un compromiso de laburo.', 'Sorry, but I have a work commitment.', array['I''m sorry, but I have a work commitment.', 'Sorry, but I''ve got a work thing.']::text[]),
  ('b1bd26c8-27d5-5816-a689-125001ee8737', 'Es de maleducado no ayudar a lavar los platos.', 'It''s rude not to help wash the dishes.', array['It''s bad manners not to help wash the dishes.', 'It''s rude not to help with the dishes.']::text[]),
  ('b382a278-896c-5513-8f97-e435bc9bf38d', 'El domingo voté y me fui a comer un asado.', 'On Sunday I voted and went to eat an asado.', array['On Sunday I voted and went to have an asado.', 'I voted on Sunday and went for an asado.']::text[]),
  ('b3cdfc01-f3d7-54cc-b122-ef900b133ba3', 'Lo feo del viaje fue el vuelo.', 'The bad part of the trip was the flight.', array['The worst part of the trip was the flight.', 'The bad thing about the trip was the flight.']::text[]),
  ('b5894986-ec33-5f57-883f-b94527bcb255', '—¿Te enojaste? —No, me puse un poco celosa.', '—Did you get angry? —No, I got a little jealous.', array['Did you get mad? No, I got a bit jealous.', 'Were you angry? No, I got a little jealous.']::text[]),
  ('b5a30746-8217-522b-9024-fd4707597c1c', '¿En qué calle estás?', 'What street are you on?', array['Which street are you on?', 'What street are you in?']::text[]),
  ('b68f2d1d-64ea-577c-a35d-5d7e0bbde772', 'Cami se fue temprano y yo todavía no había llegado.', 'Cami left early and I hadn''t arrived yet.', array['Cami left early and I hadn''t gotten there yet.', 'Cami left early and I still hadn''t arrived.']::text[]),
  ('b6bb5020-a2ab-5c28-b9db-5644110f274f', 'El profe se calentó porque llegué tarde.', 'The teacher got mad because I got there late.', array['The teacher got angry because I was late.', 'The teacher got mad because I arrived late.']::text[]),
  ('b74c29e8-37e3-5aba-b155-1b503805cc04', 'Para un extranjero es raro saludar con un beso.', 'For a foreigner, greeting people with a kiss is weird.', array['For a foreigner it''s strange to greet with a kiss.', 'To a foreigner, greeting people with a kiss is strange.']::text[]),
  ('b795b10b-e25a-51ec-957f-9cb00af42cbe', '¿En la final hinchás por el cuadro de tu viejo?', 'In the final, are you supporting your dad''s team?', array['In the final, are you rooting for your dad''s team?', 'Do you support your dad''s team in the final?']::text[]),
  ('b89d67ba-e849-54c7-8e64-c71dda04264c', '¿Pudiste comprar las entradas?', 'Were you able to buy the tickets?', array['Did you manage to buy the tickets?', 'Could you buy the tickets?']::text[]),
  ('b9d490fc-8f0e-5e5a-936e-e8532e7e14c0', 'Mi abuela todavía canta en las fiestas de la familia.', 'My grandmother still sings at family parties.', array['My grandma still sings at family gatherings.', 'My grandmother still sings at the family parties.']::text[]),
  ('bc3655e4-a7ad-5291-a238-e971ce5882f6', 'Hablando del rey de Roma, Juli está en la puerta.', 'We were just talking about her, and Juli is at the door.', array['Speak of the devil, Juli is at the door.']::text[]),
  ('bd0a511b-6124-54a8-b7a8-25bf7d4bfc15', '—¿Te pregunto algo? —Cómo no.', '—Can I ask you something? —Of course.', array['Can I ask you something? Sure.', 'May I ask you something? Of course.']::text[]),
  ('bd0e7c07-52fd-5794-a0b4-f43ffb54a589', '¿Te acordás del asado en lo de Diego?', 'Remember the asado at Diego''s?', array['Do you remember the asado at Diego''s?', 'Remember the barbecue at Diego''s place?']::text[]),
  ('bd2f2360-e806-5d3d-9126-461e2e40c2c6', '¡Qué lindo perro! ¿Cómo se llama?', 'What a cute dog! What''s his name?', array['What a cute dog! What''s her name?', 'What a nice dog! What''s its name?']::text[]),
  ('bd40533c-8c1b-5ff5-b999-a34e815182a3', 'Con el pantalón azul prefiero el buzo marrón.', 'With the blue pants, I prefer the brown sweatshirt.', array['With the blue pants I prefer the brown hoodie.', 'I prefer the brown sweatshirt with the blue pants.']::text[]),
  ('be16afe0-19d9-5e9a-81dc-fdb558a0af12', 'Prestame diez mil pesos, que no me alcanza.', 'Lend me ten thousand pesos, I don''t have enough.', array['Lend me ten thousand pesos, I''m short.', 'Lend me ten thousand pesos, it''s not enough.']::text[]),
  ('be4454df-7bf6-557f-9941-11e5259aae77', '—¿Salís con este calor? —¡Ni a palos!', '—Are you going out in this heat? —No way!', array['You''re going out in this heat? No way!', 'Are you going out in this heat? Not a chance!']::text[]),
  ('c0449fba-d7aa-5fac-9dba-fa023aaeca90', 'Che, ¿empanadas o medialunas?', 'Hey, empanadas or medialunas?', array['Hey, empanadas or croissants?']::text[]),
  ('c05e36a2-378f-5ecc-bc17-0006f4bd6b4a', 'Ella es inglesa, pero yo no.', 'She''s English, but I''m not.', array['She is English, but I am not.', 'She''s English, but not me.']::text[]),
  ('c0bc98b2-d4c3-5b22-af94-74d267c013bc', 'No sabés cuánto te lo agradezco.', 'You don''t know how much I appreciate it.', array['You have no idea how much I appreciate it.', 'You don''t know how grateful I am.']::text[]),
  ('c1523789-843b-54eb-8fa9-46c348e611ce', 'Que no te vea la vecina.', 'Don''t let the neighbor see you.', array['Make sure the neighbor doesn''t see you.']::text[]),
  ('c1f7dfba-aaf7-52a7-a05c-2427bbf50d58', 'Ella es francesa, no argentina.', 'She''s French, not Argentinian.', array['She''s French, not Argentine.', 'She is French, not Argentinian.']::text[]),
  ('c22c3ade-4e92-525f-b896-95fdc2f01a53', 'Me quedaría una semana más en Mendoza.', 'I''d stay one more week in Mendoza.', array['I would stay one more week in Mendoza.', 'I''d stay another week in Mendoza.']::text[]),
  ('c256926f-fe75-5a08-8d80-c5fa84cd09c4', 'Me alcanza con que me prestes unos pesos.', 'It''s enough if you lend me a few pesos.', array['It''s enough for me if you lend me a few pesos.', 'Lending me a few pesos is enough.']::text[]),
  ('c320763c-2428-57cd-a8c4-14b32b56ea22', 'Empecé en el laburo nuevo.', 'I started at the new job.', array['I started the new job.', 'I started at my new job.']::text[]),
  ('c3822f57-11ae-5eb3-9e68-1b9ba2c937a2', 'El domingo a la tarde me pone mal.', 'Sunday afternoon makes me sad.', array['Sunday afternoons get me down.', 'Sunday afternoon gets me down.']::text[]),
  ('c3f1c20d-26ac-5026-8c5d-4c0513b6f4b5', 'La campera azul es muy linda, pero es muy grande.', 'The blue jacket is very nice, but it''s very big.', array['The blue jacket is very pretty, but it''s too big.', 'The blue jacket is really nice, but it''s really big.']::text[]),
  ('c49e0016-1147-5ad3-b4c8-bae88a317944', '¿El supermercado está al lado o enfrente de la escuela?', 'Is the supermarket next to the school or across from it?', array['Is the supermarket next to or across from the school?', 'Is the supermarket beside the school or across the street from it?']::text[]),
  ('c4b77245-ff5f-5443-96c7-9d2ebb998471', 'A Sofi le duele la garganta.', 'Sofi''s throat hurts.', array['Sofi has a sore throat.', 'Sofi''s throat is sore.']::text[]),
  ('c662b63c-aad4-5c6a-bee2-5974317eceb4', 'Lograr tanto en un año es increíble.', 'Achieving so much in a year is incredible.', array['Accomplishing so much in a year is incredible.', 'To achieve so much in one year is incredible.']::text[]),
  ('c6b5a1ed-e918-5508-b09e-78667bab84a6', '¿Sabés si esos bares quedan cerca del parque?', 'Do you know if those bars are near the park?', array['Do you know whether those bars are close to the park?']::text[]),
  ('c6f8edba-8766-5a1b-9eac-666f25bb1df0', 'Nosotras somos de Uruguay, pero nuestra mamá es chilena.', 'We''re from Uruguay, but our mom is Chilean.', array['We are from Uruguay, but our mom is Chilean.', 'We''re from Uruguay, but our mother is Chilean.']::text[]),
  ('c7078fd4-f852-54ba-ab32-b7f51c486dd3', 'Esperame, llego en cinco minutos.', 'Wait for me, I''ll be there in five minutes.', array['Wait for me, I''m arriving in five minutes.', 'Wait for me, I''ll be there in five.']::text[]),
  ('c735a5b9-0930-5503-96aa-13b5e63c98cd', 'En la tele dicen que mañana va a hacer calor.', 'They say on TV it''s going to be hot tomorrow.', array['On TV they say it''s going to be hot tomorrow.', 'They''re saying on TV that tomorrow will be hot.']::text[]),
  ('c76a3fac-a157-5fce-a926-bb63b572f4fd', '¿Tiene ocho años?', 'Is she eight?', array['Is he eight?', 'Is she eight years old?']::text[]),
  ('c809017d-30c6-5b7d-bc58-d4bb7b68c233', 'En el Mundial hincho por Argentina.', 'In the World Cup I support Argentina.', array['In the World Cup I root for Argentina.', 'I support Argentina in the World Cup.']::text[]),
  ('c960c6ff-2eca-5fbb-af2b-221cb203de3f', '—¿Tu novia estudia en la facu? —Sí, y labura también.', '—Does your girlfriend study at college? —Yes, and she works too.', array['Does your girlfriend go to college? Yes, and she works too.', 'Does your girlfriend study at university? Yes, and she also works.']::text[]),
  ('c968c61a-a995-5547-8fb1-af0e79fe7f84', '—¿Qué te pidió? —Que comprara leche.', '—What did she ask you to do? —To buy milk.', array['What did he ask you to do? To buy milk.', 'What did she ask you for? To buy milk.']::text[]),
  ('c9a97cd8-10c3-5f18-a064-dedccc6e42f6', 'Me reí tanto que se me cayó una lágrima.', 'I laughed so much that I shed a tear.', array['I laughed so hard a tear fell.', 'I laughed so much I shed a tear.']::text[]),
  ('ca2021cf-a97c-545f-897f-90613bfe16c1', 'Se trabó la puerta del ascensor.', 'The elevator door got stuck.', array['The elevator door jammed.', 'The elevator door is stuck.']::text[]),
  ('cb96a099-a48c-50ff-a4ad-eb1fbc2acaad', '¿Vas a traer la ensalada?', 'Are you going to bring the salad?', array['Are you bringing the salad?', 'Will you bring the salad?']::text[]),
  ('cbf4609b-691f-563c-83f5-83f974efebf8', 'Al pagar la carne para el asado, se me bloqueó la tarjeta.', 'When I was paying for the meat for the asado, my card got blocked.', array['While paying for the meat for the asado, my card got blocked.', 'When I paid for the asado meat, my card was blocked.']::text[]),
  ('cc304e5b-037c-5dd4-a739-e5611a79cf01', '¿Te apurás o nos vamos sin vos?', 'Will you hurry up, or do we leave without you?', array['Are you going to hurry, or are we leaving without you?', 'Will you hurry up or do we go without you?']::text[]),
  ('ccee055f-ecc4-5e28-9710-5884a08429fa', '—¿Venís al asado el domingo? —Capaz, pero llego tarde.', '—Are you coming to the asado on Sunday? —Maybe, but I''ll be late.', array['Are you coming to the asado on Sunday? Maybe, but I''ll get there late.', 'Are you coming to the barbecue Sunday? Maybe, but I''ll be late.']::text[]),
  ('cd16e3bb-5c1a-5705-b9ae-f7d243df0e94', '¿No tendrás cambio de diez mil?', 'Do you happen to have change for ten thousand?', array['Would you happen to have change for ten thousand?', 'You wouldn''t have change for ten thousand, would you?']::text[]),
  ('cd28d9a3-72eb-5481-8594-62d6a3611360', 'Hoy hincho por el cuadro que nunca ganó nada.', 'Today I''m supporting the team that has never won anything.', array['Today I''m rooting for the team that never won anything.', 'Today I support the team that has never won anything.']::text[]),
  ('cd484101-159e-5996-9a4c-5a32d83fecf6', 'En el recreo nadie quería volver a clase.', 'At recess nobody wanted to go back to class.', array['At recess no one wanted to go back to class.', 'During recess nobody wanted to return to class.']::text[]),
  ('cd7d69a9-f302-55ec-a7ef-3f2501d9790b', '¿Ves a Juan? Está en la esquina.', 'Can you see Juan? He''s on the corner.', array['Do you see Juan? He''s on the corner.', 'See Juan? He''s at the corner.']::text[]),
  ('cd860d07-d226-59e9-bcac-0f723e7a701a', 'Juli está distinta desde que se mudó a Mendoza.', 'Juli seems different since she moved to Mendoza.', array['Juli has been different since she moved to Mendoza.', 'Juli is different since she moved to Mendoza.']::text[]),
  ('d0326d54-8662-522c-a0d7-eccaa73a8d83', '—¿Me cuidás las plantas? —Cómo no, doña Rosa.', '—Can you look after my plants? —Of course, Doña Rosa.', array['Will you look after my plants? Of course, Doña Rosa.', 'Can you take care of my plants? Sure, Doña Rosa.']::text[]),
  ('d2b7668c-0e41-54d2-aab9-17e998e81b45', 'Mi vieja siempre está diciendo que me extraña.', 'My mom is always saying she misses me.', array['My mom always says she misses me.', 'My mom keeps saying she misses me.']::text[]),
  ('d2be006d-b534-5e58-8f4c-626c0c4546c2', 'Un paquete de caramelos, por favor.', 'A pack of candy, please.', array['A pack of candies, please.', 'A bag of candy, please.']::text[]),
  ('d2e101e4-f147-554f-8245-5b6705472f44', 'No le mientas a Lucía, ya sabe todo.', 'Don''t lie to Lucía, she already knows everything.', array['Don''t lie to Lucía, she knows everything already.']::text[]),
  ('d2f6e3e9-879c-5917-b8e4-2a5f04c337f4', 'No le cuentes nada, es re chusma.', 'Don''t tell her anything, she''s such a gossip.', array['Don''t tell him anything, he''s such a gossip.', 'Don''t tell her anything, she''s a real gossip.']::text[]),
  ('d2fa1b48-9820-5404-9ee4-a52b737a6db3', 'La inmobiliaria pide un mes de depósito.', 'The real estate agency asks for one month''s deposit.', array['The real estate agency asks for a one-month deposit.', 'The agency asks for one month''s deposit.']::text[]),
  ('d384a7d9-e52a-5e4b-a03f-ed06d4418a35', 'Cuando sepa algo del viaje, te llamo.', 'When I know something about the trip, I''ll call you.', array['When I know anything about the trip, I''ll call you.', 'As soon as I hear something about the trip, I''ll call you.']::text[]),
  ('d436351b-6dfb-576c-bb17-3c93dfc6333a', 'Perdón, ¿sos la moza?', 'Excuse me, are you the waitress?', array['Sorry, are you the waitress?', 'Excuse me, are you the server?']::text[]),
  ('d45c4e61-ded8-5369-84a5-2b90fe1c04df', '¿Viste? Subió el subte.', 'See? The subway fare went up.', array['See? The subway went up.', 'Did you see? The subway fare went up.']::text[]),
  ('d499ca77-0536-5403-af1b-3e56d3b58409', 'Diez mil pesos un café: me afanaron.', 'Ten thousand pesos for a coffee: they overcharged me.', array['Ten thousand pesos for a coffee: I got ripped off.', 'Ten thousand pesos for a coffee: they ripped me off.']::text[]),
  ('d5680b94-4abd-5c9e-9158-56a2ff221125', 'Mi hermano siempre usa remeras amarillas.', 'My brother always wears yellow T-shirts.', array['My brother always wears yellow shirts.', 'My brother always wears yellow tees.']::text[]),
  ('d5a38e16-fe9b-59fc-8a41-fc671b36ba40', 'Voy a aprovechar los precios y comprar los pasajes hoy.', 'I''m going to take advantage of the prices and buy the tickets today.', array['I''m going to make the most of the prices and buy the tickets today.', 'I''ll take advantage of the prices and buy the tickets today.']::text[]),
  ('d796c423-4626-56c6-bc7a-b7692e9f0be5', '¡Qué contento te pusiste!', 'You were so happy!', array['You got so happy!', 'How happy you got!']::text[]),
  ('d84f3ff1-145a-509b-a7c2-29cf1c71aafc', 'Yo hablaría con el dueño antes de pagar.', 'I''d talk to the landlord before paying.', array['I would talk to the owner before paying.', 'I''d speak to the landlord before paying.']::text[]),
  ('d8c6540d-2384-54e7-953c-88c647fa0fab', 'Contame lo de ayer.', 'Tell me about yesterday.', array['Tell me what happened yesterday.', 'Tell me about the thing yesterday.']::text[]),
  ('d8cd7811-5793-547e-9cf7-0755a5e086b5', 'Lo de anoche me molesta un poco.', 'What happened last night bothers me a little.', array['Last night''s thing bothers me a bit.', 'What happened last night bothers me a bit.']::text[]),
  ('d97e8474-dcfd-51d0-8bea-2a0e3a09d0b9', 'Como te iba diciendo, Mati tiene novia.', 'As I was saying, Mati has a girlfriend.', array['Like I was saying, Mati has a girlfriend.', 'As I was telling you, Mati has a girlfriend.']::text[]),
  ('da4b1c40-cc1f-548e-8680-aea19aeb56e5', 'Es mejor que cambies plata en el centro.', 'It''s better to change money downtown.', array['It''s better that you change money downtown.', 'You''d better exchange money downtown.']::text[]),
  ('da73000d-69ae-5985-9751-ca396e1680fc', 'Si hubiéramos comprado el auto, ahora no estaríamos esperando el bondi.', 'If we had bought the car, we wouldn''t be waiting for the bus now.', array['If we''d bought the car, we wouldn''t be waiting for the bus now.', 'If we had bought the car, we wouldn''t be waiting for the bus right now.']::text[]),
  ('dbf511f7-24fd-54d2-b33b-6034e380187c', '¿Hay otro probador?', 'Is there another fitting room?', array['Is there another changing room?', 'Is there another dressing room?']::text[]),
  ('dc009998-f6a0-5a7f-ac7a-4dfe8121cd61', '¿Me contás uno de tus chistes?', 'Will you tell me one of your jokes?', array['Can you tell me one of your jokes?', 'Will you tell me a joke of yours?']::text[]),
  ('dc8b24e3-72fd-5db6-b07e-55a9a2a30357', '¿Una tostada?', 'A piece of toast?', array['A toast?', 'A slice of toast?']::text[]),
  ('dcc97d9d-ac8c-574d-b17f-ccd2da7d603c', 'En la facu alquilaba una pieza, pero después me mudé con Sofi.', 'In college I rented a room, but then I moved in with Sofi.', array['In college I used to rent a room, but later I moved in with Sofi.', 'At university I rented a room, but then I moved in with Sofi.']::text[]),
  ('dd173aed-fd48-52ed-bd3c-c6480ad7738a', 'Llamame si necesitás algo.', 'Call me if you need anything.', array['Call me if you need something.', 'Give me a call if you need anything.']::text[]),
  ('dddfa41f-caa0-5c9b-92fa-5c53a1ddae8f', 'Hola, tío, ¿cómo andás?', 'Hi, uncle, how are you doing?', array['Hi, uncle, how''s it going?', 'Hello, uncle, how are you?']::text[]),
  ('de7ab3a5-ddcd-5c42-a798-533881dca60d', '¿Vas conociendo gente acá?', 'Are you getting to know people here?', array['Are you meeting people here?', 'Are you getting to meet people here?']::text[]),
  ('dec16213-d01c-5221-8115-0c73c936c4c0', 'Me asusté y corrí hasta la parada del bondi.', 'I got scared and ran to the bus stop.', array['I got scared and ran all the way to the bus stop.', 'I got frightened and ran to the bus stop.']::text[]),
  ('dec2e418-c385-57dd-b9ec-cdfd4e6df3a7', 'A veces tomo café con leche.', 'Sometimes I have coffee with milk.', array['Sometimes I drink coffee with milk.', 'I sometimes have coffee with milk.']::text[]),
  ('df8ed202-4f56-53b3-a424-d50f0d6a66cc', 'Cuando éramos chicos, ¿vos no eras más alta que yo?', 'When we were kids, weren''t you taller than me?', array['When we were kids, weren''t you taller than I was?', 'When we were little, weren''t you taller than me?']::text[]),
  ('df936213-e34e-5946-8f49-65ffa83ced1e', 'Pablo es argentino, pero ella es estadounidense.', 'Pablo is Argentinian, but she''s American.', array['Pablo is Argentine, but she''s American.', 'Pablo is Argentinian, but she is from the United States.']::text[]),
  ('e203b7ad-42b6-5e88-a24b-1de901b8105f', '¿Sacaste la ropa del lavarropas?', 'Did you take the clothes out of the washing machine?', array['Did you take the laundry out of the washing machine?', 'Did you get the clothes out of the washer?']::text[]),
  ('e264f2bc-94d3-5d04-95d3-8bccecb64316', 'Ese pantalón rosa es muy feo, ¿no?', 'Those pink pants are very ugly, right?', array['Those pink pants are really ugly, aren''t they?', 'Those pink pants are very ugly, no?']::text[]),
  ('e2a90b18-3896-573f-8531-e7525dc408ce', 'Rocío camina porque no tiene auto.', 'Rocío walks because she doesn''t have a car.', array['Rocío walks because she has no car.', 'Rocío goes on foot because she doesn''t have a car.']::text[]),
  ('e35c41ec-e72e-5148-85d8-ca733262f9e8', '¿Vos hubieras ahorrado con ese sueldo?', 'Would you have saved on that salary?', array['Would you have saved money on that salary?', 'Would you have saved with that salary?']::text[]),
  ('e48120f6-a028-5e20-a50c-c9b8d35d2528', 'Me aseguró que devolvería todo.', 'She assured me she''d give back everything.', array['He assured me he''d give everything back.', 'She assured me she would return everything.']::text[]),
  ('e5605b6d-7b08-5c31-a4a5-7c506fc46dc0', '¿Ese pantalón azul es de Nico?', 'Are those blue pants Nico''s?', array['Do those blue pants belong to Nico?']::text[]),
  ('e5f396c0-bd62-5dfd-bcb6-eb560981f62b', 'Esa remera negra es muy chica para Mati.', 'That black T-shirt is too small for Mati.', array['That black T-shirt is very small for Mati.', 'That black shirt is too small for Mati.']::text[]),
  ('e73d771a-c358-582f-96e3-e9acbffb50ba', 'Este verano pienso viajar a Córdoba con mis viejos.', 'This summer I''m planning to travel to Córdoba with my parents.', array['This summer I plan to travel to Córdoba with my parents.', 'I''m planning to go to Córdoba with my parents this summer.']::text[]),
  ('e8451e77-94c1-522d-9eee-870f82cce7b2', '¿Dejaste el DNI en casa otra vez?', 'Did you leave your ID at home again?', array['You left your ID at home again?']::text[]),
  ('e84cf890-910a-511b-8d2c-194f90f16b08', 'Estoy en Rosario, ¿y vos?', 'I''m in Rosario, and you?', array['I''m in Rosario, what about you?', 'I''m in Rosario, how about you?']::text[]),
  ('e9f9bdac-f7c0-5900-80e6-8d9bec40d84a', 'Te estoy diciendo que el depto nuevo es carísimo.', 'I''m telling you the new apartment is super expensive.', array['I''m telling you that the new apartment is really expensive.', 'I''m telling you the new apartment is very expensive.']::text[]),
  ('ea4e21ab-58e1-5a6c-9d43-e10b63391c01', 'Queda poco hielo, pero dale que va.', 'There''s not much ice left, but it''s good enough.', array['There''s little ice left, but it''ll do.', 'There isn''t much ice left, but it''s fine.']::text[]),
  ('eb00affd-bf22-5ab7-b629-8aa7293986f9', '¿Querés una cuchara para el arroz?', 'Do you want a spoon for the rice?', array['Would you like a spoon for the rice?', 'Want a spoon for the rice?']::text[]),
  ('ebae1e99-e93a-5ef5-86cc-b57eced66104', 'Volví a la pieza y el despertador todavía sonaba.', 'I went back to the room and the alarm was still going off.', array['I went back to the room and the alarm clock was still ringing.', 'I returned to the room and the alarm was still going.']::text[]),
  ('ebb508b6-cd83-59f8-b8a4-37f5a39892f2', '¿Se rompió el ascensor?', 'Did the elevator break down?', array['Did the elevator break?', 'Is the elevator broken?']::text[]),
  ('eff24e85-b2c0-587d-b3c3-6102341ce3a1', 'Este mes llueve todos los días.', 'This month it rains every day.', array['It''s raining every day this month.', 'This month it''s raining every day.']::text[]),
  ('f0c89518-1bfc-51e2-9b15-8d0cf97838eb', '¿Cuánto sale arreglar un inodoro que pierde agua?', 'How much is it to fix a leaking toilet?', array['How much does it cost to fix a leaking toilet?', 'How much is it to repair a toilet that leaks?']::text[]),
  ('f0ca3374-97b2-5b86-a818-4de498bf0e11', 'Mi hermano es re pesado y así y todo lo quiero.', 'My brother is really annoying and even so I love him.', array['My brother is really annoying and I love him anyway.', 'My brother is a real pain and I still love him.']::text[]),
  ('f25aa2f2-122d-5d67-ad12-b0a7aa4f62a0', 'Insisto en que te lleves el paraguas.', 'I insist that you take the umbrella.', array['I insist you take the umbrella.', 'I insist that you take the umbrella with you.']::text[]),
  ('f30de138-3220-5416-9bf3-160aad6ab4a6', '—¿Y el laburo? —Cada vez peor.', '—And work? —Worse and worse.', array['How''s work? Worse and worse.', 'And the job? Worse every time.']::text[]),
  ('f316179b-3fc7-5c92-bd9a-87b27be53a95', 'Che, no hay nada como las empanadas de mi abuela.', 'Hey, there''s nothing like my grandmother''s empanadas.', array['Hey, there''s nothing like my grandma''s empanadas.']::text[]),
  ('f34f52ab-74dd-526d-80e5-6bf30d10990c', 'Voy a la cancha con mis amigas.', 'I''m going to the game with my friends.', array['I''m going to the stadium with my friends.', 'I''m going to the match with my friends.']::text[]),
  ('f3b2b5d3-ac1f-5388-98b2-a7c3680b51bc', '¿El wifi empeoró o es mi compu?', 'Did the wifi get worse or is it my computer?', array['Did the wifi get worse or is it my laptop?', 'Has the wifi gotten worse, or is it my computer?']::text[]),
  ('f439438e-001e-5c58-9900-5373054659ca', 'Con diez mil pesos no me alcanza.', 'Ten thousand pesos isn''t enough.', array['Ten thousand pesos is not enough for me.', 'I can''t get by with ten thousand pesos.']::text[]),
  ('f613cc3f-dbf8-5aad-ba0f-036320e6ad45', 'Saqué efectivo porque en efectivo es más barato.', 'I got cash because it''s cheaper in cash.', array['I took out cash because it''s cheaper in cash.', 'I withdrew cash because paying cash is cheaper.']::text[]),
  ('f617bcbf-58d1-528e-9d8a-1a4b242d99c4', 'Ella no es mi gata, es de mi abuela.', 'She''s not my cat, she''s my grandmother''s.', array['She isn''t my cat, she''s my grandma''s.', 'She''s not my cat, she belongs to my grandmother.']::text[]),
  ('f64db5f8-dede-56fa-8e2f-a076d6d27831', 'Queremos recorrer el norte y conocer las cataratas.', 'We want to travel around the north and see the waterfalls.', array['We want to tour the north and see the waterfalls.', 'We want to travel around the north and visit the falls.']::text[]),
  ('f66f0e39-12af-5fc9-abbe-afe81b369d3d', 'Mi vieja es genial, posta.', 'My mom is great, honestly.', array['My mom is awesome, seriously.', 'My mom is great, for real.']::text[]),
  ('f7b76d5c-5b32-544b-8536-20b53644b8a1', '—¡Buen día! —Buenas, ¿qué onda?', '—Good morning! —Hi there, what''s up?', array['Good morning! Hey, what''s up?', 'Morning! Hi, how''s it going?']::text[]),
  ('f7c0e9ae-d827-5b11-8eab-2d660d9360df', 'Me robaron la bici y fui a hacer la denuncia.', 'They stole my bike and I went to file a police report.', array['My bike was stolen and I went to report it.', 'They stole my bike and I went to file a report.']::text[]),
  ('f7e4ac7d-0f4e-5e23-845c-4e47ba12091f', 'No podés rechazar un laburo así.', 'You can''t turn down a job like that.', array['You can''t reject a job like that.', 'You can''t say no to a job like that.']::text[]),
  ('f7f39cc9-afcb-5903-8c8e-66a56fe9c3c3', 'Sofi hizo el postre.', 'Sofi made the dessert.', array['Sofi made dessert.']::text[]),
  ('f8040082-ae23-548d-aac8-a961cf5e0536', 'El mueble de la cocina es viejo, pero me gusta.', 'The kitchen cabinet is old, but I like it.', array['The kitchen cupboard is old, but I like it.', 'The kitchen unit is old, but I like it.']::text[]),
  ('f807a0d1-c0aa-511d-9acb-226e204b14ef', 'Ayer hice una ensalada re rica.', 'I made a really tasty salad yesterday.', array['Yesterday I made a really delicious salad.', 'I made a really good salad yesterday.']::text[]),
  ('f83714ac-aca9-5981-969f-4e28eedb0960', '—¿Qué hiciste el finde? —Nada, estuve en casa.', '—What did you do over the weekend? —Nothing, I was at home.', array['What did you do this weekend? Nothing, I stayed home.', 'What did you do on the weekend? Nothing, I was home.']::text[]),
  ('f83e5275-5a68-5a4c-a496-9161f76a604d', '—¿Me siento acá? —¡Cómo no!', '—Can I sit here? —Of course!', array['Should I sit here? Of course!', 'May I sit here? Sure!']::text[]),
  ('f8669746-ed77-568e-bc09-5ed933ff04d6', '—¿Qué tomás? —Lo que sea.', '—What are you drinking? —Anything is fine.', array['What are you having? Whatever.', 'What are you drinking? Anything.']::text[]),
  ('f8a59f46-422d-58f3-b44a-769d81568966', 'Che, ¿ella es australiana o es de Estados Unidos?', 'Hey, is she Australian or is she from the United States?', array['Hey, is she Australian or American?', 'Hey, is she Australian or from the US?']::text[]),
  ('f8c94a7f-877a-5031-8605-6ab40c86e424', 'Mi gata tiene nueve años y mi perro, dos.', 'My cat is nine and my dog is two.', array['My cat is nine and my dog, two.', 'My cat is nine years old and my dog is two.']::text[]),
  ('f95098fa-e1cb-5942-9ae2-ac38f693eeb1', 'Mi gato se come mi comida y después se hace el dormido.', 'My cat eats my food and then pretends to be asleep.', array['My cat eats my food and then acts like he''s asleep.', 'My cat eats my food and then plays asleep.']::text[]),
  ('f98e9521-c264-54ab-b35a-e5490496cd37', 'Es lindo; por otro lado, hay mucho ruido.', 'It''s nice; on the other hand, there''s a lot of noise.', array['It''s nice; then again, it''s very noisy.', 'It''s pretty; on the other hand, there''s a lot of noise.']::text[]),
  ('f9bc5597-7fed-5de1-8770-80c852e9d60a', 'Ya le avisé a mi hermana.', 'I already told my sister.', array['I already let my sister know.', 'I''ve already told my sister.']::text[]),
  ('fa173c54-e05c-5a6e-aa9f-72ecb87caa2c', 'Elijan el color y se lo traigo.', 'Choose the color and I''ll bring it to you.', array['Pick the color and I''ll bring it to you.', 'Choose the color and I''ll bring it for you.']::text[]),
  ('fa36e175-17fe-531a-b552-da884260b695', '¿Doña Marta vive sola?', 'Does Doña Marta live alone?', array['Does Mrs. Marta live alone?', 'Does Doña Marta live by herself?']::text[]),
  ('faa8cb8e-08f7-5f97-977d-d6a88aadb7a7', 'Pablo no está, está jugando al fútbol.', 'Pablo isn''t here, he''s playing soccer.', array['Pablo''s not here, he''s playing soccer.', 'Pablo isn''t in, he''s playing soccer.']::text[]),
  ('fb908576-08ac-51bf-902e-166d3696d55c', '—¿Qué número es? —No sé, preguntá en el kiosco.', '—What number is it? —I don''t know, ask at the kiosco.', array['What number is it? I don''t know, ask at the kiosk.', 'Which number is it? I don''t know, ask at the kiosco.']::text[]),
  ('fbd5f7d8-1a2d-56cb-a325-bfb51f9504d8', 'Me dio mucha angustia.', 'I got really upset.', array['It made me really anxious.', 'I felt really upset.']::text[]),
  ('fd43aacb-736a-53ed-ad2d-cabe41317158', 'Frená, que el semáforo está en rojo.', 'Brake, the light is red.', array['Brake, the traffic light is red.', 'Stop, the light is red.']::text[]),
  ('fef0f511-e7fd-5f85-9f1b-cbc5f502fcf5', 'Leí en el diario que el proyecto del subte nuevo fue aprobado.', 'I read in the newspaper that the new subway project was approved.', array['I read in the paper that the new subway project was approved.', 'I read in the newspaper that the new subway project got approved.']::text[]),
  ('fffb156e-c679-5efc-9bdc-bae27ca32d70', '—¿Es tu chocolate? —No, es de mis abuelos.', '—Is it your chocolate? —No, it''s my grandparents''.', array['Is that your chocolate? No, it''s my grandparents''.', 'Is it your chocolate? No, it belongs to my grandparents.']::text[]),
  ('9a15dae4-5005-59f5-ba23-b584893f6285', 'Disculpá, ¿podríamos ver la carta?', 'Excuse me, could we see the menu?', array['Sorry, could we see the menu?', 'Excuse me, could we have the menu?']::text[])
) as v (id, es, en, en_alt)
where s.id = v.id::uuid and s.es = v.es and s.en = v.en and s.en_alt = '{}';
